(function(){const d=window.POLICE_DATA;if(!d)return;const sources=[{"id":"local-guru-actual-social","name":"Guru Academy / Guru Police · ข้อสอบจริงสังคม 100 ข้อ","platform":"local-pdf","url":"ข้อสอบจริง/สังคม/ข้อสอบสังคม Extract.pdf","local":true,"status":"reviewed","note":"ข้อสอบจริงสังคม พร้อมโจทย์และตัวเลือกข้อความครบ 100 ข้อ"},{"id":"local-guru-actual-social-answer","name":"Guru Academy / Guru Police · เฉลยละเอียดสังคม","platform":"local-pdf","url":"ข้อสอบจริง/สังคม/Copy of 01. เฉลยละเอียด สังคม.pdf","local":true,"status":"reviewed","note":"ใช้ตรวจคำตอบและคำอธิบายข้อ 1–100"}];for(const s of sources)if(!d.sources.some(x=>x.id===s.id))d.sources.push(s);const rows=[{"id":"actual-guru-social-001","subject":"social","question_number":1,"question_text":"ข้อใดไม่่่ใช่คำเรียก Good Governance ในภาษาไทย","choices":{"A":"ธรรมรัฐ","B":"บรรษัทภิบาล","C":"หลักธรรมาภิบาล","D":"การบริหารจัดการรวมภาครัฐ"},"correct_answer":"D","source_answer":"D. การบริหารจัดการรวมภาครัฐ","explanation_th":["คำศัพท์ทางการที่ใช้และมีความหมายเทียบเคียงกับ Good Governance คือ การบริหารกิจการบ้านเมืองที่ดี ไม่่ใช่การบริหารจัดการรวมภาครัฐ อธิบายตัวเลือกอื่น ดังนี้ บ ธรรมรัฐ เป็นคำแรก ๆ ในยุควิกฤตเศรษฐกิจบี 2580 ที่นักวิชาการนำมาใช้แปลความหมายของคำว่า Good Governance เพื่อสื่อถึงรัฐที่มีการบริหารจัดการที่ดีและมีคุณธรรม 2 บรรษัทภิบาล เป็นคำแปลของ Corporate Governance ซึ่งก็คือ Good Governance ที่ถูกนำมาปรับใช้ในบริบท ของภาคธุรกิจหรือเอกชน 3) หลักธรรมาภิบาล เป็นคำแปลที่เป็นทางการ ได้้รับความนิยมสูงสุด และครอบคลุมความหมายของ Good Governance ในภาษาไทยได้้ชัดเจนที่สุดในปัจจุบัน"],"explanation_image":"assets/real-social-explanations/q001.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 1 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-002","subject":"social","question_number":2,"question_text":"หากตำรวจใช้รถยนต์ของทางราชการไปทำธุระส่วนตัว ถือว่าละเลยหลักธรรมาภิบาลข้อใด มากที่สุด","choices":{"A":"หลักการมีส่วนร่วม","B":"หลักนิติธรรม","C":"หลักความรับผิดชอบ","D":"หลักความคุ้มค่า อ ง ะ ร"},"correct_answer":"D","source_answer":"D. หลักความคุ้มค่า อ ง ะ ร","explanation_th":["หลักความคุ้มค่า คือการบริหารจัดการและใช้ทรัพยากรของรัฐให้เกิดประโยชน์สูงสุด การนำรถยนต์ราชการไปใช้ ส่วนตัวจึงเป็นการผิดหลักข้อนี้โดยตรง อธิบายตัวเลือกอื่น ดังนี้. 1) หลักการมีส่วนร่วม คือการเปิดโอกาสให้ประชาชนมีส่วนร่วมรับรู้และเสนอความเห็น 2) หลักนิติธรรม คือการใช้กฎหมาย กฎระเบียบอย่างเป็นธรรมและเสมอภาค 3) หลักความรับผิดชอบ คือการตระหนักในสิทธิหน้ำที่และรับผิดชอบต่อผลการกระทำของตน"],"explanation_image":"assets/real-social-explanations/q002.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 2 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-003","subject":"social","question_number":3,"question_text":"หลักธรรมาภิบาลปรากฏครั้งแรกในรายงานขององค์กรใด (ตม.67)","choices":{"A":"WTO","B":"WORLD BANK","C":"ASEAN","D":"UNITED STATES CONGRESS"},"correct_answer":"B","source_answer":"B. WORLD BANK","explanation_th":["WORLD BANK (ธนาคารโลก) เป็นองค์กรแรกที่นำคำนี้มาใช้อย่างเป็นทางการในรายงานการพัฒนาแห่งโลก (World Development Report) ปี ค.ศ. 1989 อธิบายตัวเลือกอื่น ดังนี้ 1) WTO (องค์การการค้าโลก) เนนเรื่องข้อตกลงและระเบียบการค้าระหว่างประเทศ 3) ASEAN (สมาคมประชาชาติแห่งเอเชียตะวันออกเฉียงใต้) เน้นความร่วมมือระดับภูมิภาค 4) UNITED STATES CONGRESS (รัฐสภาสหรัฐอเมริกา) เป็นสถาบันนิติบัญญัติของสหรัฐฯ พพแพแไแงแงฤงฤางญไนฟนาแหหไแงแกแงวงไวไวไวไวไวไวไวไวไวว ว วีึื"],"explanation_image":"assets/real-social-explanations/q003.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 3 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-004","subject":"social","question_number":4,"question_text":"การเปิดโอกาสให้สมาชิกชุมชนได้้แสดงความคิดเห็นและแก้ปัญหาของท้องถิ่น สอดคล้องกับหลักธรรมาภิบาลข้อใดมากที่สุด (ปป.64)","choices":{"A":"หลักคุณธรรม","B":"หลักการมีส่วนร่วม","C":"หลักความรับผิดชอบ","D":"หลักความโปร่งใส"},"correct_answer":"B","source_answer":"B. หลักการมีส่วนร่วม","explanation_th":["หลักการมีส่วนร่วม คือการเปิดโอกาสให้ประชาชนหรือสมาชิกชุมชนได้้แสดงความเห็น ร่วมคิด ร่วมตัดสินใจ และร่วมแก้ปัญหา อธิบายตัวเลือกอื่น ดังนี้ 1) หลักคุณธรรม คือการยึดมั่นในความถูกต้อง ดีงาม ชื่อสัตย์สุจริต 3) หลักความรับผิดชอบ คือการใส่ใจให้บริการและรับผิดชอบต่อหน้ำที่ 4) หลักความโปร่งใส คือการทำงานที่เปิดเผย ตรงไปตรงมา ตรวจสอบได้้."],"explanation_image":"assets/real-social-explanations/q004.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2564,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 4 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-005","subject":"social","question_number":5,"question_text":"การนำกระดาษที่ใช้แล้วกลับมาใช้ใหม่ในหน้ำที่ยังใช้ได้้ และยังใช้โทรศัพท์สำนักงานรุ่นเก่าที่ยังทำงานได้้ดี สอดคล้องกับหลักธรรมาภิบาลข้อใดมากที่สุด (ตม.67)","choices":{"A":"หลักนิติธรรม","B":"หลักการมีส่วนร่วม","C":"หลักความโปร่งใส","D":"หลักความคุ้มค่า"},"correct_answer":"D","source_answer":"D. หลักความคุ้มค่า","explanation_th":["หลักความคุ้มค่า คือการใช้ทรัพยากรที่มีอยู่จำกัดให้เกิดประโยชน์สูงสุดและประหยัดที่สุด wu การใช้กระดาษข้้า (รียูส) หรือใช้อุปกรณ์เดิมที่ยังทำงานได้้ อธิบายตัวเลือกอื่น ดังนี้ 1) หลักนิติธรรม คือการยึดหลักกฎหมาย 2) หลักความมีส่วนร่วม คือการให้ประชาชนเข้ามามีบทบาท 3) หลักความโปร่งใส คือการเปิดเผยข้อมูล ตรวจสอบได้้"],"explanation_image":"assets/real-social-explanations/q005.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 5 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-006","subject":"social","question_number":6,"question_text":"การใช้ช้อนกลางถือเป็นบรรทัดฐานใด (ปป.69)","choices":{"A":"จารีต","B":"กฎหมาย","C":"วิถีประชา","D":"วิถีชาวบ้าน"},"correct_answer":"C","source_answer":"C. วิถีประชา","explanation_th":["วิถีประชา Ao ธรรมเนียมปฏิบัติ มารยาททั่วไปในชีวิตประจำวันที่สังคมยอมรับ หากผ่าผืนไม่ได้้มีโทษรุนแรง การกินข้าวใช้ข้อนกลางจัดอยู่ในกลุ่มนี้ อธิบายตัวเลือกอื่น ดังนี้. 1) จารีต คือ กฎศีลธรรม หากผ่าฝืนสังคมจะต่อต้านและลงโทษรุนแรง 2) กฎหมาย คือ ข้อบังคับของรัฐ มีบทลงโทษชัดเจนและบังคับใช้เด็ดขาด 4) วิถีขาวบ้าน มีความหมายเดียวกันกับวิถีประชา แต่คำว่าวิถีประชาเป็นศัพท์ทางการกว่า"],"explanation_image":"assets/real-social-explanations/q006.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 6 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-007","subject":"social","question_number":7,"question_text":"บรรทัดฐานทางสังคมข้อใดที่ต้องยึดถือและปฏิบัติตาม (ปป.68)","choices":{"A":"จารีต","B":"กฎหมาย","C":"วิถีประชา","D":"วิถีชาวบ้าน"},"correct_answer":"B","source_answer":"B. กฎหมาย","explanation_th":["กฎหมาย เป็นบรรทัดฐานทางสังคมที่รัฐกําหนดขึ้นเพื่อจัดระเบียบสังคม มีสภาพบังคับที่เด็ดขาด สมาชิกในสังคมทุก คนต้องยึดถือและปฏิบัติตาม อย่างหลีกเลี่ยงไม่่ได้้ หากผ่าฝืนจะมีบทลงโทษที่เป็นทางการและเป็นลายลักษณ์อักษรที่ชัดเจน คีย์เวิร์ตคำว่า ต้องยึดถือและปฏิบัติตาม อธิบายตัวเลือกอื่น ดังนี้ 1) จารีต เป็นบรรทัดฐานที่ผังลึกเรื่องความดี ความชั่ว สังคมคาดหวังอย่างแรงกล้าให้คนปฏิบัติตาม แตไม่่มีบทลงโทษเป็นลาย ลักษณ์อักษรจากรัฐ (บทลงโทษคือการถูกสังคมประณาม รังเกียจ หรือขับไล่) 3) วิถีประชา uae 4) วิถีชาวบ้าน คือเรื่องเดียวกัน เป็นแค่มารยาท ธรรมเนียม หรือความเคยขินทั่วไปในสังคมที่ควรปฏิบัติ (เช่น การกล่าวคำทักทาย มารยาทบนโต๊ะอาหาร) หากใครไม่่ทำตาม ก็แค่อาจถูกมองแปลกๆ หรือถูกนินทา แต่ไม่่ถึงขั้นถูก ประณามรุนแรง ซา"],"explanation_image":"assets/real-social-explanations/q007.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 7 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-008","subject":"social","question_number":8,"question_text":"การทำผิดบรรทัดฐานในข้อใด หากฝ่าฝืนจะได้้รับบทลงโทษอย่างหลีกเลี่ยงไม่่ได้้ เนื่องจากมีบทลงโทษระบุไว้อย่างชัดเจนที่สุดจากสังคม (ปป.66)","choices":{"A":"จารีต","B":"กฎหมาย","C":"วิถีประชา","D":"วิถีชาวบ้าน"},"correct_answer":"B","source_answer":"B. กฎหมาย","explanation_th":["กฎหมาย มีลักษณะเฉพาะคือมีบทลงโทษเป็นลายลักษณ์อักษรจากรัฐ บังคับใช้เด็ดขาด และมีความชัดเจนที่สุด หากผ่าฝืนจะได้้รับบทลงโทษอย่างหลีกเลี่ยงไม่ได้้ อธิบายตัวเลือกอื่น ดังนี้ 1) จารีต มีบทลงโทษจากสังคม (เช่น รังเกียจ Fula) แต่ไม่ได้้เขียนไว้เป็นลายลักษณ์อักษรขัดเจนเหมือนกฎหมาย 3) และ 0) วิถีประชา/วิถีชาวบ้าน บทลงโทษเบาบางมาก เช่น การถูกตําหนิ หรือมองด้วยสายตาแปลก ๆ"],"explanation_image":"assets/real-social-explanations/q008.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 8 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-009","subject":"social","question_number":9,"question_text":"ไม่่ว่าจะรวยหรือจนก็อยู่ภายใต้กรอบกฎหมาย สอดคล้องกับข้อใด (อก.65)","choices":{"A":"คติธรรม","B":"วัตถุธรรม","C":"สหธรรม","D":"เนติธรรม"},"correct_answer":"D","source_answer":"D. เนติธรรม","explanation_th":["เนติธรรม คือวัฒนธรรมทางกฎหมาย การที่ทุกคนอยู่ภายใต้กรอบกฎหมายอย่างเท่าเทียมกันจึงสอดคล้องกับ เนติธรรมที่สุด อธิบายตัวเลือกอื่น ดังนี้ 1) คติธรรม คือ วัฒนธรรมด้านความเชื่อและจิตใจ 2) วัตถุธรรม คือ วัฒนธรรมทางวัตถุ สิ่งประดิษฐ์ บ้านเรือน เครื่องมือ 3) สหธรรม คือ วัฒนธรรมด้านมารยาทและประเพณีทางสังคม"],"explanation_image":"assets/real-social-explanations/q009.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2565,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 9 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-010","subject":"social","question_number":10,"question_text":"นายเอในวันที่บรรจุราชการแต่งตัวไม่่สุภาพและใช้คำพูดไม่่สุภาพ ผิดหลักข้อใด (ปป.67)","choices":{"A":"สหธรรม","B":"กฎหมาย","C":"จริยธรรม","D":"เนติธรรม"},"correct_answer":"A","source_answer":"A. สหธรรม","explanation_th":["สหธรรม คือวัฒนธรรมทางสังคมที่ช่วยให้คนอยู่ร่วมกันได้้อย่างราบรื่น เช่น มารยาททางสังคม การแต่งกายที่ เหมาะสมตามกาลเทศะ และการใช้ภาษาที่สุภาพ อธิบายตัวเลือกอื่น ดังนี้. 2) กฎหมาย การแต่งกายไม่่สุภาพไม่ได้้มีบทลงโทษตามกฎหมายอาญาหรือแพ่งโดยตรง 3) จริยธรรม เป็นหลักความประพฤติกว้าง ๆ 4) เนติธรรม เป็นเรื่องของกฎหมายและสิทธิหน้ำที่"],"explanation_image":"assets/real-social-explanations/q010.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 10 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-011","subject":"social","question_number":11,"question_text":"ข้อใดทำให้สังคมอยู่ร่วมกันด้วยความเรียบร้อยและมีความสุข (ปป.69)","choices":{"A":"การจัดระเบียบสังคม","B":"การมีบทลงโทษที่รุนแรง","C":"การมีฐานะทางเศรษฐกิจที่เท่าเทียม","D":"การแยกกันอยู่ตามความเชื่อ"},"correct_answer":"A","source_answer":"A. การจัดระเบียบสังคม","explanation_th":["การจัดระเบียบสังคม คือ กระบวนการที่สังคมสร้างกฎเกณฑ์ บรรทัดฐาน และบทบาทหน้ำที่ เพื่อควบคุมให้สมาชิก 'ในสังคมอยู่ร่วมกันได้้อย่างเป็นระเบียบเรียบร้อยและสงบสุข อธิบายตัวเลือกอื่น ดังนี้ 2) การมีบทลงโทษที่รุนแรง ไม่ได้้การันตีความสุขและอาจสร้างความหวาดระแวง 3) การมีฐานะเศรษฐกิจที่เท่าเทียม เป็นอุดมคติที่เกิดขึ้นได้้ยากในโลกความจริงและไม่่ใช่บัจจัยหลักที่จัดระเบียบสังคม 4) การแยกกันอยู่ตามความเชื่อ จะทำให้สังคมเกิดความแตกแยก ขาดความสามัคคี ุุุ่่ ทุ ุุ่ ุณุ ไผไสฯ!ๆไเไุวไวไวไวไโวโไโไโ้นลวกว้ว้วไวไโทโ"],"explanation_image":"assets/real-social-explanations/q011.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 11 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-012","subject":"social","question_number":12,"question_text":"ข้อใดอธิบายเกี่ยวกับวัฒนธรรมผิด (อก.60)","choices":{"A":"เป็นสิ่งที่มนุษย์สร้างขึ้น","B":"จัดเป็นมรดกทางสังคม","C":"ไม่่สามารถเปลี่ยนแปลงได้้ ต้องคงไว้เป็นหนึ่งเดียวเสมอ","D":"หลายครั้งมาจากรูปแบบวิถีชีวิต"},"correct_answer":"C","source_answer":"C. ไม่่สามารถเปลี่ยนแปลงได้้ ต้องคงไว้เป็นหนึ่งเดียวเสมอ","explanation_th":["ไม่่สามารถเปลี่ยนแปลงได้้ ต้องคงไว้เป็นหนึ่งเดียวเสมอ เป็นคำกล่าวที่ผิด เพราะวัฒนธรรมมีพลวัต คือมีการ เปลี่ยนแปลง ปรับปรุง และลื่นไหลอยู่เสมอเพื่อให้สอดคล้องกับสภาพแวดล้อมและยุคสมัยที่เปลี่ยนไป อธิบายตัวเลือกอื่น ดังนี้ 1) เป็นสิ่งที่มนุษย์สร้างขึ้น ถูกต้อง เพราะวัฒนธรรมไม่ใช่สิ่งที่เกิดขึ้นเองตามธรรมชาติ แต่เป็นสิ่งที่มนุษย์คิดค้นขึ้น 2) จัดเป็นมรดกทางสังคม ถูกต้อง เพราะวัฒนธรรมต้องมีการถ่ายทอดจากรุ่นสู่รุ่น 4) หลายครั้งมาจากรูปแบบวิถีชีวิต ถูกต้อง เพราะวัฒนธรรมคือแบบแผนการดําเนินชีวิตของคนในสังคม"],"explanation_image":"assets/real-social-explanations/q012.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2560,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 12 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-013","subject":"social","question_number":13,"question_text":"ข้อใดถือว่าเป็นการขัดเกลาทางสังคม (ปป.69)","choices":{"A":"ทารกร้องไห้เมื่อรู้สึกหิวนม","B":"แม่สอนลูกเย็บผ้า","C":"เด็กชายวัยรุ่นเริ่มมีเสียงแตกหนุ่ม","D":"ชายหนุ่มสะดุ้งเมื่อได้้ยินเสียงฟ้าผ่า"},"correct_answer":"B","source_answer":"B. แม่สอนลูกเย็บผ้า","explanation_th":["แม่สอนลูกเย็บผ้า เป็นการถ่ายทอดความรู้ ทักษะ และระเบียบแบบแผนของสังคมจากคนรุ่นหนึ่งสู่อีกรุนหนึ่ง เพื่อให้สมาชิกเรียนรู้และนำไปใช้ในชีวิตประจำวันได้้ อธิบายตัวเลือกอื่น ดังนี้ 1) ทารกร้องไห้เมื่อรู้สึกหิวนม เป็นสัญชาตญาณและการตอบสนองทางชีววิทยา ไม่่ใช่การเรียนรู้ทางสังคม 3) เด็กชายวัยรุ่นเริ่มมีเสียงแตกหนุ่ม เป็นการเปลี่ยนแปลงทางสรีรวิทยาและฮอร์โมนตามธรรมชาติ 4) ขายหนุ่มสะดุ้งเมื่อได้้ยินเสียงพ้าผ่า เป็นปฏิกิริยาสะท้อนกลับทางร่างกายสู่สิ่งเร้า"],"explanation_image":"assets/real-social-explanations/q013.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 13 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-014","subject":"social","question_number":14,"question_text":"พฤติกรรมในข้อใดจัดเป็นการขัดเกลาทางสังคมทางอ้อม (ปป.62)","choices":{"A":"ต้นสอนแม่ของเขาใช้คอมพิวเตอร์","B":"แก้วเล่นกีฬากับเพื่อน ๆ ที่โรงเรียน","C":"ยอดสอนการบ้านคณิตศาสตร์ให้เมธา","D":"มหาวิทยาลัยจัดอบรมคุณธรรมแก่นักศึกษา"},"correct_answer":"B","source_answer":"B. แก้วเล่นกีฬากับเพื่อน ๆ ที่โรงเรียน","explanation_th":["แก้วเล่นกีฬากับเพื่อน ๆ ที่โรงเรียน เป็นการขัดเกลาทางอ้อม เพราะแก้วได้้ซึมขับการเรียนรู้กฎกติกา การรู้แพ้รู้ชนะ และการอยู่ร่วมกับผู้อื่นผ่านการเล่น โดยไม่ได้้เป็นสถานการณ์ที่ตั้งใจมานั่งอบรมสั่งสอนกันตรง ๆ อธิบายตัวเลือกอื่น ดังนี้ 1) ต้นสอนแม่ของเขาใช้คอมพิวเตอร์ เป็นการขัดเกลาทางตรง (ผู้สอนมีความตั้งใจถ่ายทอดความรู้ชัดเจน) 3) ยอดสอนการบ้านคณิตศาสตร์ให้เมธา เป็นการขัดเกลาทางตรง (มีจุดมุ่งหมายเพื่อสอนให้รู้) 4) มหาวิทยาลัยจัดอบรมคุณธรรมแก่นักศึกษา เป็นการขัดเกลาทางตรง (เป็นสถาบันที่มีหน้ำที่และเบ้าหมายในการอบรม สั่งสอนอย่างชัดเจน)"],"explanation_image":"assets/real-social-explanations/q014.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2562,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 14 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-015","subject":"social","question_number":15,"question_text":"ข้อใดเป็นการขัดเกลาทางสังคมทางอ้อม (ตม.67)","choices":{"A":"ครูสอนหนังสือนักเรียน","B":"แม่สอนลูก","C":"โรงเรียนเปิดอบรมเด็ก","D":"เด็กอ่านหนังสือนิตยสาร"},"correct_answer":"D","source_answer":"D. เด็กอ่านหนังสือนิตยสาร","explanation_th":["เด็กอ่านหนังสือนิตยสาร จัดเป็นการขัดเกลาทางอ้อมผ่านสื่อมวลชน เด็กจะขึมขับค่านิยม ความเชื่อ และพฤติกรรม ผ่านเนื้อหาที่อ่าน โดยที่สื่อเหล่านั้นไม่ได้้มุ่งหน้ำสอนเด็กโดยตรงเหมือนในห้องเรียน อธิบายตัวเลือกอื่น ดังนี้ 1) ครูสอนหนังสือนักเรียน เป็นการขัดเกลาทางตรง (ผ่านสถาบันการศึกษา) 2) แม่สอนลูก เป็นการขัดเกลาทางตรง (ผ่านสถาบันครอบครัว) 3) โรงเรียนเปิดอบรมเด็ก เป็นการขัดเกลาทางตรง (มีการจัดหลักสูตรหรือเบ้าหมายเพื่อสั่งสอนขัดเจน) OE"],"explanation_image":"assets/real-social-explanations/q015.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 15 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-016","subject":"social","question_number":16,"question_text":"ข้อใดกล่าวถึงลักษณะของวัฒนธรรมได้้ถูกต้องที่สุด","choices":{"A":"เป็นสิ่งที่มนุษย์สร้างขึ้นจากสัญชาตญาณ","B":"วัฒนธรรมเป็นสิ่งที่มนุษย์สร้างขึ้น เกิดจากการเรียนรู้ และสามารถเปลี่ยนแปลงได้้","C":"วัฒนธรรมเป็นสิ่งที่คนในสังคมต้องเรียนรู้และไม่่ต้องสืบทอดต่อกัน","D":"วัฒนธรรมเป็นสิ่งที่ไม่่เปลี่ยนแปลง"},"correct_answer":"B","source_answer":"B. วัฒนธรรมเป็นสิ่งที่มนุษย์สร้างขึ้น เกิดจากการเรียนรู้ และสามารถเปลี่ยนแปลงได้้","explanation_th":["วัฒนธรรมเป็นสิ่งที่มนุษย์สร้างขึ้น เกิดจากการเรียนรู้ และสามารถเปลี่ยนแปลงได้้ เป็นนิยามที่ครอบคลุมลักษณะ สำคัญของวัฒนธรรมได้้ครบถ้วนและถูกต้องที่สุด อธิบายตัวเลือกอื่น ดังนี้ 1) เป็นสิ่งที่มนุษย์สร้างขึ้นจากสัญชาตญาณ ผิด เพราะวัฒนธรรมเกิดจากการเรียนรู้ไม่่ใช่สัญชาตญาณ 3) วัฒนธรรมเป็นลิ่งที่คนในสังคมต้องเรียนรู้และไม่่ต้องสืบทอดต่อกัน ผิด เพราะวัฒนธรรมต้องมีการสืบทอดและถ่ายทอด ต่อกันเสมอ 4) วัฒนธรรมเป็นสิ่งที่ไม่่เปลี่ยนแปลง ผิด เพราะวัฒนธรรมมีการเปลี่ยนแปลงตามยุคสมัยและค่านิยมอยู่เสมอ"],"explanation_image":"assets/real-social-explanations/q016.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 16 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-017","subject":"social","question_number":17,"question_text":"สถาบันใดทางสังคมที่เป็นพื้นฐานพัฒนาตนเองในด้านต่าง ๆ (ปป.68)","choices":{"A":"สถาบันครอบครัว","B":"สถาบันการศึกษา","C":"สถาบันการเมืองการปกครอง","D":"สถาบันทางเศรษฐกิจ"},"correct_answer":"A","source_answer":"A. สถาบันครอบครัว","explanation_th":["สถาบันครอบครัว เป็นสถาบันทางสังคมที่เก่าแก่ พื้นฐานที่สุดและสำคัญที่สุด เพราะเป็นจุดเริ่มต้นของการขัดเกลา ทางสังคม ปลูกผังบุคลิกภาพ และพัฒนาตนเองตั้งแต่แรกเกิด อธิบายตัวเลือกอื่น ดังนี้ 2) สถาบันการศึกษา เป็นสถาบันที่รับช่วงต่อจากครอบครัว เน้นให้ความรู้ทางวิชาการและวิชาชีพ 9) สถาบันการเมืองการปกครอง เน้นการจัดระเบียบสังคม สร้างความสงบเรียบร้อย และบริหารประเทศ 4) สถาบันทางเศรษฐกิจ เน้นการผลิต การกระจาย และการบริโภคสินค้าและบริการเพื่อปากท้องของคนในสังคม"],"explanation_image":"assets/real-social-explanations/q017.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 17 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-018","subject":"social","question_number":18,"question_text":"วัฒนธรรมในข้อใดได้้รับอิทธิพลจากพุทธศาสนา (ตม.66)","choices":{"A":"การทอดกฐิน","B":"การตั้งศาลพระภูมิ","C":"การบูชาพระตรีมูรติ","D":"การขลิบ"},"correct_answer":"A","source_answer":"A. การทอดกฐิน","explanation_th":["การทอดกฐิน เป็นประเพณีและพิธีกรรมที่สืบทอดมาจากพุทธประวัติโดยตรง ซึ่งเป็นการถวายผ้าไตรจีวรแด่พระสงข์ ที่จำพรรษาครบ 3 เดือน อธิบายตัวเลือกอื่น ดังนี้ 2) การตั้งศาลพระภูมิ ได้้รับอิทธิพลจากความเชื่อเรื่องผีสางเทวดาผสมผสานกับศาสนาพราหมณ์-ฮินดู 3) การบูชาพระตรีมูรติ ได้้รับอิทธิพลจากศาสนาพราหมณ์-ฮินดู (การบูชาเทพเจ้าสูงสุด 3 พระองค์ คือ พระพรหม พระวิษณุ พระศิวะ) 4) การขลิบ เป็นพิธีกรรมที่ได้้รับอิทธิพลมาจากศาสนาอิสลามและศาสนายูดาห์"],"explanation_image":"assets/real-social-explanations/q018.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 18 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-019","subject":"social","question_number":19,"question_text":"พระราชดำรัสของสมเด็จพระนางเจ้าสิริกิติ์ พระบรมราชินีนาถ พระบรมราชชนนีพันปีหลวง ที่ว่า ‘ไม่่มีใครดู ฉันจะดูเอง’ กล่าวถึงศิลปะการแสดงใด","choices":{"A":"หนังใหญ่","B":"หุ่นกระบอก","C":"ลิเก","D":"โขน"},"correct_answer":"D","source_answer":"D. โขน","explanation_th":["Tou สมเด็จพระนางเจ้าสิริกิตี้ พระบรมราชินีนาถ พระบรมราชชนนีพันปีหลวง ทรงมีพระมหากรุณาธิคุณในการ พื้นฟูศิลปะการแสดงโขนที่กําลังจะเลือนหายไปให้กลับมามีชีวิตชีวาอีกครั้ง จนเกิดเป็น โขนพระราชทาน ในบัจจุบัน อธิบายตัวเลือกอื่น ดังนี้ 1) หนังใหญ่ เป็นมหรสพที่ใช้แผ่นหนังฉลุลายเชิดหน้ำจอผ้าขาว มักแสดงเรื่องรามเกียรติ์ 2) หุ่นกระบอก เป็นมหรสพพื้นบ้านของไทยที่ใช้หุ่นเชิด 3) ลิเก เป็นศิลปะการแสดงพื้นบ้านที่เน้นการร้องและรา มีต้นกําเนิดผสมผสานมาจากทางมุสลิม(ดิเกร์) และการสวดคฤหัสถ์ ชรชรโญไ ป"],"explanation_image":"assets/real-social-explanations/q019.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 19 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-020","subject":"social","question_number":20,"question_text":"งานประเพณีทานขันข้าว เป็นประเพณีของท้องถิ่นไทยภูมิภาคใด","choices":{"A":"ภาคใต้","B":"ภาคกลาง","C":"ภาคเหนือ","D":"ภาคตะวันออกเฉียงเหนือ"},"correct_answer":"C","source_answer":"C. ภาคเหนือ","explanation_th":["ภาคเหนือ ประเพณีทานขันข้าว เป็นประเพณีการทำบุญอุทิศส่วนกุศลไปให้บรรพบุรุษที่ล่วงลับไปแล้ว โดยมักจะจัด 'ในช่วงเทศกาลสำคัญ เช่น สงกรานต์ หรือเข้าพรรษา อธิบายตัวเลือกอื่น ดังนี้ 1) ภาคใต้ มีประเพณีที่คล้ายคลึงกันคือ ประเพณีสารทเดือนสิบ (งานบุญชิงเปรต) 2) ภาคกลาง มีประเพณีทำบุญวันสารทไทย 4) ภาคตะวันออกเฉียงเหนือ มีประเพณีบุญข้าวสาก หรือบุญข้าวประดับดิน"],"explanation_image":"assets/real-social-explanations/q020.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 20 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-021","subject":"social","question_number":21,"question_text":"ถ้าต้องการเรียนประเพณีทางภาคเหนือเกี่ยวกับชาวไทยใหญ่บวชสามเณร ควรไปดูประเพณีใด (ปป.66)","choices":{"A":"ทำขวัญข้าว","B":"ปอยส่างลอง","C":"แห่ปราสาทผึ้ง","D":"กวนข้าวยาคู"},"correct_answer":"B","source_answer":"B. ปอยส่างลอง","explanation_th":["ปอยส่างลอง เป็นประเพณีการบรรพชาสามเณรตามความเชื่อของชาวไทใหญ่ ในภาคเหนือ โดยเฉพาะจังหวัด แม่ฮ่องสอน จะมีการแต่งกายให้ผู้บวชอย่างสวยงาม เลียนแบบเจ้าชายสิทธัตถะก่อนออกบวช อธิบายตัวเลือกอื่น ดังนี้ 1) ทำขวัญข้าว เป็นประเพณีเพื่อบูชาพระแม่โพสพและเรียกขวัญข้าวให้ได้้ผลผลิตดี พบได้้ทั่วไปในสังคมเกษตรกรรม 3) แห่ปราสาทผึ้ง เป็นประเพณีของทางภาคอีสานทำในวันออกพรรษา 4) กวนข้าวยาคู เป็นประเพณีทางพุทธศาสนา มักจัดขึ้นในวันมาฆบูชาหรือวันวิสาขบูชา"],"explanation_image":"assets/real-social-explanations/q021.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 21 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-022","subject":"social","question_number":22,"question_text":"การทำพิธีขนข้าวเป็นประเพณีที่เกี่ยวข้องกับวิถีชีวิตในเรื่องใดมากที่สุด (ปป.69)","choices":{"A":"ศาสนา","B":"ครอบครัว","C":"อาชีพ","D":"ที่อยู่อาศัย"},"correct_answer":"C","source_answer":"C. อาชีพ","explanation_th":["อาชีพ เพราะพิธีขนข้าว เป็นความเชื่อและประเพณีที่ผูกพันกับวิถีชีวิตของชาวนา ซึ่งเป็นอาชีพหลักของคนไทย ในสังคมเกษตรกรรม เพื่อแสดงความขอบคุณพระแม่โพสพและขอให้ได้้ผลผลิตดีในฤดูกาลหน้ำ อธิบายตัวเลือกอื่น ดังนี้. 1) ศาสนา แม้จะมีความเชื่อเข้ามาเกี่ยวข้อง แต่แก่นแท้เกิดจากการประกอบอาชีพเกษตรกรรม 2) ครอบครัว เป็นหน่วยที่ร่วมกันทำกิจกรรม แต่ไม่่ใช่สาเหตุหลักของประเพณีนี้ 4) ที่อยู่อาศัย ไม่่ได้้มีความเกี่ยวข้องโดยตรงกับประเพณีการขนข้าว"],"explanation_image":"assets/real-social-explanations/q022.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 22 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-023","subject":"social","question_number":23,"question_text":"ประเพณี ‘วิ่งควาย’ เป็นประเพณีของภาคใด (ปป.62)","choices":{"A":"ภาคตะวันออก","B":"ภาคตะวันตก","C":"ภาคกลาง","D":"ภาคใต้"},"correct_answer":"A","source_answer":"A. ภาคตะวันออก","explanation_th":["ภาคตะวันออก ประเพณีวิ่งควายเป็นประเพณีเก่าแก่และมีชื่อเสียงมากที่สุดของจังหวัดชลบุรีซึ่งตั้งอยู่ในภาค ตะวันออก จัดขึ้นเพื่อทำขวัญควายและให้ควายได้้พักผ่อนหลังจากการทำนา อธิบายตัวเลือกอื่น ดังนี้ 2) ภาคตะวันตก ไม่่มีประเพณีวิ่งควายเป็นเอกลักษณ์หลัก 3) ภาคกลาง มีประเพณีที่เกี่ยวกับเกษตรกรรมเข่นกัน เช่น ทำขวัญข้าว แตไม่่ใช่วิ่งควาย 4) mela มีประเพณีที่เกี่ยวกับสัตว์ เช่น ชักพระแข่งเรือ หรือกีฬาชนโค (วัวชน) — ย ็ั้ญ้ญญ ้้นนฬาไั้ไไไฬ็๊้็โซในี์์:"],"explanation_image":"assets/real-social-explanations/q023.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2562,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 23 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-024","subject":"social","question_number":24,"question_text":"ประเพณี ‘ยี่เป็ง’ เป็นประเพณีของภาคใดของประเทศไทย (ตม.67)","choices":{"A":"ภาคเหนือ","B":"ภาคใต้","C":"ภาคกลาง","D":"ภาคตะวันออก"},"correct_answer":"A","source_answer":"A. ภาคเหนือ","explanation_th":["เหนือ ประเพณียี่เบ็ง (หรือวันเพ็ญเดือนยี่ของชาวล้านนา) คือประเพณีลอยกระทงของทางภาคเหนือ มีเอกลักษณ์ที่ 'โดดเด่นคือการจุดผางประทีปและการปล่อยโคมลอย ขึ้นสู่ท้องพ้าเพื่อบูชาพระเกศแก้วจุฬามณี อธิบายตัวเลือกอื่น ดังนี้ 2) ใต้ ประเพณีสำคัญในช่วงใกล้เคียงกันคือ ซักพระ หรือ ลากพระ 3) กลาง คือประเพณีลอยกระทงตามปกติ (ลอยในแมน้ำ) 4) ตะวันออก ไม่่มีประเพณียี่เบ็ง"],"explanation_image":"assets/real-social-explanations/q024.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 24 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-025","subject":"social","question_number":25,"question_text":"แนวคิด Human-Centered Development เริ่มขึ้นในแผนพัฒนาเศรษฐกิจและสังคมแห่งชาติฉบับใด","choices":{"A":"ฉบับที่ 8","B":"ฉบับที่ 4","C":"ฉบับที่ 1","D":"ฉบับที่ 12"},"correct_answer":"A","source_answer":"A. ฉบับที่ 8","explanation_th":["ฉบับที่ 8 แผนพัฒนาฯ ฉบับที่ 8 (พ.ศ. 2540 - 2544) ถือเป็นจุดเปลี่ยนครั้งสำคัญของไทยที่เปลี่ยนแนวคิดจากการ เน้นการเติบโตทางเศรษฐกิจ มาเป็นแนวคิดคนเป็นศูนย์กลางของการพัฒนา (Human-Centered Development) อธิบายตัวเลือกอื่น ดังนี้ 2) ฉบับที่ 4 เน้นการพื้นฟูเศรษฐกิจและสังคมหลังเหตุการณ์ความไม่่สงบทางการเมือง 3) ฉบับที่ 1 เน้นการสร้างโครงสร้างพื้นฐานของประเทศ (น้้าไหล ไฟสว่าง ทางดี) 4) ฉบับที่ 12 เน้นการประยุกต์ใช้ปรัชญาของเศรษฐกิจพอเพียงและเบ้าหมายการพัฒนาที่ยั่งยืน (5065)"],"explanation_image":"assets/real-social-explanations/q025.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 25 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-026","subject":"social","question_number":26,"question_text":"ตำรวจนายหนึ่งกู้เงินนอกระบบมาใช้จ่ายฟุ่มเฟือยจนมีหนี้สินล้นพ้นตัวและตัดสินใจทุจริตเพื่อหาเงินมาใช้หนี้ พฤติกรรมนี้แสดงว่าขาดองค์ประกอบใดของเศรษฐกิจพอเพียงมากที่สุด","choices":{"A":"ขาดความพอประมาณและขาดเงื่อนไขคุณธรรม","B":"ขาดความรู้เรื่องกฎหมาย","C":"ขาดภูมิคุ้มกันในการจับกุมคนร้าย","D":"ขาดความมีเหตุผลและขาดการมีส่วนร่วม"},"correct_answer":"A","source_answer":"A. ขาดความพอประมาณและขาดเงื่อนไขคุณธรรม","explanation_th":["ขาดความพอประมาณและขาดเงื่อนไขคุณธรรม การใช้จ่ายพุ่มเพือยจนเป็นหนี้ แสดงถึงการขาดหลักความ 'พอประมาณและการตัดสินใจ ทุจริต แสดงถึงการขาดเงื่อนไขคุณธรรม อธิบายตัวเลือกอื่น ดังนี้. 2) ขาดความรู้เรื่องกฎหมาย ไม่่ใช่องค์ประกอบหลัก 3 ห่วง 2 เงื่อนไข ของหลักปรัชญาของเศรษฐกิจพอเพียง 3) ขาดภูมิคุ้มกันในการจับกุมคนร้าย การมีภูมิคุ้มกันในหลักเศรษฐกิจพอเพียงหมายถึงการเตรียมพร้อมรับความเสี่ยง ไม่่ใช่ทักษะการจับกุม 4) ขาดความมีเหตุผล และขาดการมีส่วนร่วม การมีส่วนร่วม ไม่่ใช่องค์ประกอบของหลักปรัชญาของเศรษฐกิจพอเพียง"],"explanation_image":"assets/real-social-explanations/q026.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 26 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-027","subject":"social","question_number":27,"question_text":"โครงการแก้มลิงเป็นโครงการพระราชดำริที่จัดตั้งขึ้นเพื่อแก้ไขปัญหาในข้อใดเป็นหลัก (ปป.69)","choices":{"A":"ปัญหาดินเปรี้ยว","B":"ปัญหาน้ำท่วม","C":"ปัญหาน้ำเน่าเสีย","D":"ปัญหาป่าไม่้เสื่อมโทรม"},"correct_answer":"B","source_answer":"B. ปัญหาน้ำท่วม","explanation_th":["ปัญหาน้้าท่วม โครงการแก้มลิงมีแนวคิดจากการที่ลิงกักตุนกล้วยไว้ในกระพุ่งแก้ม โดยใช้พื้นที่ลุ่มเพื่อกักเก็บน้้าฝน หรือน้้าหลากไว้ชั่วคราว แล้วค่อย ๆ ระบายลงทะเลเมื่อระดับน้้าทะเลลดลง เพื่อช่วยบรรเทาปัญหาน้้าท่วมขัง อธิบายตัวเลือกอื่น ดังนี้ 1) ปัญหาดินเปรี้ยว เป็นเบ้าหมายของโครงการแกล้งดิน (ทำให้ดินเปรี้ยวจัดแล้วใช้น้้าขะล้างพร้อมใส่ปูนมาร์ล) 3) ปัญหาน้้าเน่าเสีย เป็นเบ้าหมายของโครงการกังหันน้้าชัยพัฒนาและการใช้ผักตบชวาหรือน้ำดีไล่นาเสีย 4) ปัญหาบ่าไม่้เลื่อมโทรม เป็นเบ้าหมายของโครงการปลูกป่า 3 อย่าง ประโยชน์ 4 อย่าง และฝายขะลอน้้า evo"],"explanation_image":"assets/real-social-explanations/q027.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 27 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-028","subject":"social","question_number":28,"question_text":"การมีเงินออมไว้ใช้ยามฉุกเฉินจำเป็น ตรงกับหลักการใดในปรัชญาเศรษฐกิจพอเพียง","choices":{"A":"พอประมาณ","B":"มีภูมิคุ้มกันที่ดี","C":"มีเหตุผล","D":"ความรู้"},"correct_answer":"B","source_answer":"B. มีภูมิคุ้มกันที่ดี","explanation_th":["มีภูมิคุ้มกันที่ดี การมีภูมิคุ้มกันในตัวที่ดี หมายถึง การเตรียมตัวให้พร้อมรับผลกระทบและการเปลี่ยนแปลงต่าง ๆ ที่จะเกิดขึ้นในอนาคต การออมเงินสํารองไว้ใช้ยามฉุกเฉินจึงเป็นการสร้างภูมิคุ้มกันทางการเงินอย่างขัดเจน อธิบายตัวเลือกอื่น ดังนี้ 1) พอประมาณ คือความพอดีในการดําเนินชีวิต ไม่่เบียดเบียนตนเองและผู้อื่น 3) มีเหตุผล คือการตัดสินใจกระทำการต่าง ๆ อย่างมีสติ โดยพิจารณาจากเหตุปัจจัยและผลที่คาดว่าจะเกิดขึ้น 4) ความรู้ เป็นส่วนหนึ่งของเงื่อนไขไม่่ใช่หลัก 3 ห่วงโดยตรง"],"explanation_image":"assets/real-social-explanations/q028.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 28 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-029","subject":"social","question_number":29,"question_text":"การดำเนินชีวิตด้วยการประหยัดและไม่่ใช้จ่ายในสิ่งที่ไม่่จำเป็น ตรงกับหลักเศรษฐกิจพอเพียงข้อใด (ปป.64)","choices":{"A":"แบบก้าวหน้ำ","B":"แบบพื้นฐาน","C":"แบบก้าวทีละนิด","D":"แบบอนาคต"},"correct_answer":"B","source_answer":"B. แบบพื้นฐาน","explanation_th":["แบบพื้นฐาน เศรษฐกิจพอเพียงแบบพื้นฐาน (ระดับบุคคลและครอบครัว) คือการดําเนินชีวิตที่เน้นความพอมีพอกิน พึ่งพาตนเองได้้เป็นหลัก ประหยัด ลดรายจ่ายที่ไม่่จำเป็น และประกอบอาชีพสุจริต อธิบายตัวเลือกอื่น ดังนี้ 1) แบบก้าวหน้ำ คือเศรษฐกิจพอเพียงระดับกลุ่มหรือชุมชน ที่มีการรวมกลุ่มกัน (เช่น สหกรณ์) เพื่อสร้างเครือข่าย ช่วยเหลือกัน และขยายกิจการเพื่อสังคม 3) แบบก้าวทีละนิด เป็นคำหลอกที่ไม่่มีในหลักทฤษฎีนี้ 4) แบบอนาคต เป็นคำหลอกที่ไม่่มีในหลักทฤษฎีนี้"],"explanation_image":"assets/real-social-explanations/q029.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2564,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 29 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-030","subject":"social","question_number":30,"question_text":"ตามหลักเกษตรทฤษฎีใหม่ ให้เกษตรกรแบ่งพื้นที่ที่ใช้ปลูกไม่้ยืนต้นร้อยละเท่าใด (ตม.66)","choices":{"A":"10","B":"20","C":"30","D":"40"},"correct_answer":"C","source_answer":"C. 30","explanation_th":["30 หลักการแบ่งพื้นที่เกษตรทฤษฎีใหม่ขั้นที่ 1 กําหนดสัดส่วนไว้ที่ 30 : 30 : 30 : 10 โดยสัดส่วน 30% หนึ่งในนั้น คือการปลูกไม่้ผล ไม่้ยืนต้น พืชผัก fils พืชสมุนไพร เพื่อใช้เป็นอาหารประจำวันและนำไปจำหน่าย อธิบายตัวเลือกอื่น ดังนี้ 1) 10 คือ สัตส่วนสําหรับเป็นที่อยู่อาศัย เลี้ยงสัตว์ ถนนหนทาง และโรงเรือน 2) 20 เป็นตัวเลขหลอก (ไม่่มีในสัดส่วนเกษตรทฤษฎีใหม่) 4) 40 เป็นตัวเลขหลอก"],"explanation_image":"assets/real-social-explanations/q030.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 30 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-031","subject":"social","question_number":31,"question_text":"ไทยแลนด์ 4.0 ตรงกับข้อใด (ตม.67)","choices":{"A":"เป็นยุคเกษตรกรรม","B":"เป็นยุคอุตสาหกรรมหนัก","C":"เป็นยุคอุตสาหกรรมเบา","D":"เป็นยุคเศรษฐกิจที่ขับเคลื่อนด้วยนวัตกรรม"},"correct_answer":"D","source_answer":"D. เป็นยุคเศรษฐกิจที่ขับเคลื่อนด้วยนวัตกรรม","explanation_th":["เป็นยุคเศรษฐกิจที่ขับเคลื่อนด้วยนวัตกรรม นโยบาย Thailand 4.0 มุ่งเน้นการเปลี่ยนโครงสร้างเศรษฐกิจ จากแบบเดิมไปสู่ ปล[นอ-8อ5อส Economy คือเศรษฐกิจที่ขับเคลื่อนด้วยนวัตกรรม เทคโนโลยี และความคิดสร้างสรรค์ อธิบายตัวเลือกอื่น ดังนี้ 1) เป็นยุคเกษตรกรรม ตรงกับ Thailand 1.0 (เน้นเกษตรกรรมตั้งเติม ปลูกข้าว เลี้ยงหมู) 2) เป็นอุตสาหกรรมหนัก ตรงกับ Thailand 3.0 (เน้นอุตสาหกรรมหนัก รถยนต์ อิเล็กทรอนิกส์ การส่งออก) 3) เป็นยุคอุตสาหกรรมเบา ตรงกับ Thailand 2.0 (เน้นอุตสาหกรรมเบา สิ่งทอ เครื่องหนัง เครื่องดื่ม) โชโนน้วอไผไ้นนน้โ้้ฝฝเซ"],"explanation_image":"assets/real-social-explanations/q031.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 31 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-032","subject":"social","question_number":32,"question_text":"ต้องการศึกษาวัฒนธรรมของประเทศจีน สามารถศึกษาได้้จากประเทศใด (ปป.66)","choices":{"A":"ไทย ลาว","B":"พม่า กัมพูชา","C":"สิงคโปร์ เวียดนาม","D":"มาเลเซีย อินโดนีเซีย"},"correct_answer":"C","source_answer":"C. สิงคโปร์ เวียดนาม","explanation_th":["สิงคโปร์ เวียดนาม เนื่องจากเวียดนาม เคยตกอยู่ภายใต้การปกครองของจีนนับพันปี จึงรับอิทธิพลทางวัฒนธรรมจีน มาอย่างลึกซึ้ง เช่น ลัทธิขงจื้อ คติธรรมเนียมต่าง ๆ ส่วนสิงคโปร์เป็นประเทศที่มีประชากรเชื้อสายจีนอาศัยอยู่เป็นชนกลุ่มใหญ่ ที่สุดของประเทศ ทำให้มีวัฒนธรรมแบบจีนที่เด่นชัด อธิบายตัวเลือกอื่น ดังนี้ 1) ไทย ลาว ได้้รับอิทธิพลผสมผสาน แต่ค่อนไปทางอินเดียมากกว่า (พุทธศาสนาเถรวาท, พราหมณ์-ฮินดู) 2) หม่า กัมพูชา ได้้รับอิทธิพลหลักจากอารยธรรมอินเดีย ทั้งด้านศาสนาและสถาบัตยกรรม 4) มาเลเซีย อินโดนีเซีย บัจจุบันได้้รับอิทธิพลหลักจากศาสนาอิสลาม และวัฒนธรรมมลายู"],"explanation_image":"assets/real-social-explanations/q032.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 32 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-033","subject":"social","question_number":33,"question_text":"ข้อใดไม่่ใช่สาเหตุของการเปลี่ยนแปลงการปกครองของคณะราษฎร (ปป.69)","choices":{"A":"ปัญหาเศรษฐกิจตกต่ำและการดุลข้าราชการออก","B":"การได้้รับอิทธิพลทางความคิดแบบประชาธิปไตยจากชาติตะวันตก","C":"การสนับสนุนและส่งเสริมระบอบสมบูรณาญาสิทธิราชย์","D":"ความไม่่พอใจในการผูกขาดอำนาจการบริหารประเทศของกลุ่มเจ้านาย"},"correct_answer":"C","source_answer":"C. การสนับสนุนและส่งเสริมระบอบสมบูรณาญาสิทธิราชย์","explanation_th":["การสนับสนุนและส่งเสริมระบอบสมบูรณาญาสิทธิราชย์ เป็นข้อที่ผิด เพราะเบ้าหมายหลักของการปฏิวัติ พ.ศ. 2475 โดยคณะราษฎร คือการยกเลิกอํานาจเด็ดขาดของพระมหากษัตริย์ในระบอบสมบูรณาญาสิทธิราชย์ แล้วเปลี่ยนเป็นระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข อธิบายตัวเลือกอื่น ดังนี้ 1) ปัญหาเศรษฐกิจตกตํําและการดุลข้าราชการออก เป็นสาเหตุจริง ผลกระทบจากเศรษฐกิจโลกตกตําหลังสงครามโลก ครั้งที่ 1 ทำให้ต้องปลดข้าราชการ เกิดความไม่่พอใจ 2) การได้้รับอิทธิพลทางความคิดแบบประชาธิปไตยจากชาติตะวันตก เป็นสาเหตุจริง กลุ่มนักเรียนทุนที่ไปเรียนยุโรปได้้รับ แนวคิดนี้มา 4) ความไม่่พอใจในการผูกขาดอํานาจการบริหารประเทศของกลุ่มเจ้านาย เป็นสาเหตุจริงของความเหลื่อมล้าในระบบ ราชการเดิม"],"explanation_image":"assets/real-social-explanations/q033.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 33 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-034","subject":"social","question_number":34,"question_text":"อารยธรรมในข้อใดเป็นต้นแบบของการปกครองระบอบประชาธิปไตย (ปป.69)","choices":{"A":"อารยธรรมอียิปต์โบราณ","B":"อารยธรรมเมโสโปเตเมีย","C":"อารยธรรมกรีก","D":"อารยธรรมโรมัน"},"correct_answer":"C","source_answer":"C. อารยธรรมกรีก","explanation_th":["อารยธรรมกรีก นครรัฐเอเธนส์ ในอารยธรรมกรีกโบราณ ได้้รับการยกย่องจากทั่วโลกว่าเป็นต้นกําเนิดของระบอบ ประชาธิปไตย โดยเป็นรูปแบบประชาธิปไตยทางตรงที่พลเมืองชายมีสิทธิเข้ารวมสภาและออกเสียงได้้โดยตรง อธิบายตัวเลือกอื่น Mil 1) อารยธรรมอียิปต์โบราณ ปกครองโดยฟาโรห์ซึ่งมีอํานาจเด็ดขาดเสมือนเทพเจ้า 2) อารยธรรมเมโสโปเตเมีย ปกครองแบบนครรัฐโดยมีกษัตริย์เป็นผู้นำ เน้นการใช้กฎหมายควบคุม เช่น ประมวลกฎหมาย ฮัมมูราบี 4) อารยธรรมโรมัน เป็นต้นแบบของระบอบสาธารณรัฐ และระบบกฎหมายที่ครอบคลุม แต่แนวคิดประชาธิปไตยบริสุทธิ์ เริ่มที่กรีก ซา"],"explanation_image":"assets/real-social-explanations/q034.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 34 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-035","subject":"social","question_number":35,"question_text":"ราชวงศ์สุดท้ายของอยุธยาคือราชวงศ์ใด (ปป.66)","choices":{"A":"ราชวงศ์อู่ทอง","B":"ราชวงศ์สุพรรณภูมิ","C":"ราชวงศ์บ้านพลูหลวง","D":"ราชวงศ์ปราสาททอง"},"correct_answer":"C","source_answer":"C. ราชวงศ์บ้านพลูหลวง","explanation_th":["ราชวงศ์บ้านพลูหลวง เป็นราชวงศ์ที่ 5 และราชวงศ์สุดท้ายของอาณาจักรอยุธยา สถาปนาโดยสมเด็จพระเพทราชา และมึกษัตริย์พระองค์สุดท้ายคือ สมเด็จพระที่นั่งสุริยาศน์อมรินทร์ (พระเจ้าเอกทัศ) ก่อนที่จะเสียกรุงศรีอยุธยาครั้งที่ 2 อธิบายตัวเลือกอื่น ดังนี้ 1) ราชวงศ์อู่ทอง เป็นราชวงศ์แรกที่สถาปนากรุงศรีอยุธยา 2) ราชวงศ์สุวรรณภูมิ เป็นราชวงศ์ที่ 2 4) ราชวงศ์ปราสาททอง เป็นราชวงค์ที่ 4 (เทคนิคจำ 5 ราชวงศ์อยุธยา: อู่ทอง - สุพรรณภูมิ - สุโขทัย - ปราสาททอง - บ้านพลูหลวง)"],"explanation_image":"assets/real-social-explanations/q035.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 35 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-036","subject":"social","question_number":36,"question_text":"การประดิษฐ์ตัวอักษรไทยเกิดขึ้นในสมัยใด (ปป.68)","choices":{"A":"สมัยธนบุรี","B":"สมัยสุโขทัย","C":"สมัยอยุธยา","D":"สมัยรัตนโกสินทร์"},"correct_answer":"B","source_answer":"B. สมัยสุโขทัย","explanation_th":["สมัยสุโขทัย พ่อขุนรามคำแหงมหาราช ทรงประดิษฐ์อักษรไทย ขึ้นเป็นครั้งแรกเมื่อปี พ.ศ. 1826 โดยดัดแปลง มาจากอักษรขอมหวัดและอักษรมอญโบราณ ซึ่งมีหลักฐานปรากฏชัดเจนบนศิลาจารึกหลักที่ 1 อธิบายตัวเลือกอื่น ดังนี้ 1) สมัยธนบุรี เป็นยุคกอบกู้เอกราชและพื้นฟูบ้านเมืองหลังเสียกรุงฯ 3) สมัยอยุธยา ตัวอักษรไทยได้้ถูกพัฒนาต่อยอดให้เขียนง่ายและเป็นระเบียบมากขึ้นแล้ว 4) สมัยรัตนโกสินทร์ ตัวอักษรไทยได้้รับการขําระ และพัฒนาจนเป็นรูปแบบมาตรฐานที่เราใช้กันอยู่ในบัจจุบัน"],"explanation_image":"assets/real-social-explanations/q036.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 36 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-037","subject":"social","question_number":37,"question_text":"ใครคือพระบิดาแห่งกฎหมายไทย (ปป.68)","choices":{"A":"พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว","B":"พระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว","C":"พระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว","D":"พระเจ้าบรมวงศ์เธอ กรมหลวงราชบุรีดิเรกฤทธิ์"},"correct_answer":"D","source_answer":"D. พระเจ้าบรมวงศ์เธอ กรมหลวงราชบุรีดิเรกฤทธิ์","explanation_th":["พระเจ้าบรมวงศ์เธอกรมหลวงราชบุรีดิเรกฤทธิ์ (พระองค์เจ้ารพีพัฒนศักดิ์) ทรงเป็นผู้ตั้งโรงเรียนกฎหมายแห่งแรก ทรงสอนวิชากฎหมาย และรวบรวมกฎหมายเป็นหมวดหมู่ จนได้้รับการยกย่องให้เป็นพระบิดาแห่งกฎหมายไทย และมีการ กําหนดให้วันที่ 7 สิงหาคม ของทุกปีเป็นวันรพี อธิบายตัวเลือกอื่น ดังนี้ 1) พระจุลจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 5) ทรงปฏิรูประบบราชการ ศาล และทรงเลิกทาส 2) พระบาทสมเด็จพระปกเกล้าเจ้าอยู่หัว (รัชกาลที่ 7) ทรงพระราชทานรัฐธรรมนูญฉบับแรก เป็นพระบิดาแห่งระบอบ ประชาธิปไตยไทย 3) พระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว (รัชกาลที่ 4) ทรงได้้รับการยกย่องเป็นพระบิดาแห่งวิทยาศาสตร์ไทย"],"explanation_image":"assets/real-social-explanations/q037.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 37 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-038","subject":"social","question_number":38,"question_text":"ปัญหาพื้นฐานทางเศรษฐกิจตรงกับข้อใด (ตม.67)","choices":{"A":"What, Why, When","B":"What, Where, How","C":"For Who, When, Why","D":"What, How, For Whom"},"correct_answer":"D","source_answer":"D. What, How, For Whom","explanation_th":["What , How , For Whom ปัญหาพื้นฐานทางเศรษฐกิจเกิดจากทรัพยากรมีจำกัดแต่ความต้องการมีไม่่จำกัด จึงต้องตอบคำถาม 3 ข้อนี้ให้ได้้คือ ผลิตอะไร (What) ผลิตอย่างไร (How) และผลิตเพื่อใคร (For Whom) อธิบายตัวเลือกอื่น ดังนี้ 1) 2) uae 3) เป็นชุดคำถามหลอกที่นำ พ/๓๐, Why, When, Where มาผสม ซึ่งไม่ได้้อยู่ในหลักทฤษฎีปัญหา พื้นฐานทางเศรษฐศาสตร์ ณงผณค้ณณซ ฐ ขข เฟ"],"explanation_image":"assets/real-social-explanations/q038.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2567,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 38 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-039","subject":"social","question_number":39,"question_text":"ประเทศใดไม่่ได้้ทำข้อตกลง RCEP (ปป.61)","choices":{"A":"อินเดีย","B":"เกาหลีใต้","C":"นิวซีแลนด์","D":"ออสเตรเลีย"},"correct_answer":"A","source_answer":"A. อินเดีย","explanation_th":["อินเดีย แม่ในช่วงแรกอินเดียจะเข้าร่วมการเจรจาด้วย แต่ได้้ตัดสินใจถอนตัวออกไปในภายหลัง (ปี 2019) ทำให้ ความตกลง RCEP (ความตกลงหุ้นส่วนทางเศรษฐกิจระดับภูมิภาค) ในบัจจุบันประกอบด้วย 15 ประเทศ คือ อาเซียน 10 ประเทศ ร่วมกับ จีน ญี่ปุ่น เกาหลีใต้ ออสเตรเลีย และนิวซีแลนด์"],"explanation_image":"assets/real-social-explanations/q039.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2561,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 39 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-040","subject":"social","question_number":40,"question_text":"อนุสัญญาในข้อใดมีสาระสำคัญในการควบคุมการเคลื่อนย้ายข้ามแดนของเสียอันตราย ซึ่งรวมถึงขยะอิเล็กทรอนิกส์","choices":{"A":"อนุสัญญาไซเตส","B":"อนุสัญญาแรมซาร์","C":"อนุสัญญาสตอกโฮล์ม","D":"อนุสัญญาบาเซิล"},"correct_answer":"D","source_answer":"D. อนุสัญญาบาเซิล","explanation_th":["อนุสัญญาบาเซิล เป็นสนธิสัญญาระหว่างประเทศที่มีเบ้าหมายหลักในการควบคุมการเคลื่อนย้ายข้ามแดนของของ เสียอันตราย เช่น ขยะอิเล็กทรอนิกส์ ขยะอุตสาหกรรม หรือขยะติดเชื้อ เพื่อปกบ้องสุขภาพของมนุษย์และลิ่งแวดล้อม อธิบายตัวเลือกอื่น ดังนี้ 1) อนุสัญญาไซเตส เน้นเรื่องการควบคุมการค้าระหว่างประเทศซึ่งชนิดสัตว์ป่าและพืชบ่าที่ใกล้สูญพันธุ์ 2) อนุสัญญาแรมชาร์ เน้นเรื่องการอนุรักษ์และการใช้ประโยชน์พื้นที่ขุ่มน้ำอย่างยั่งยืน 3) อนุสัญญาสตอกโสล์ม เน้นเรื่องการคุ้มครองสุขภาพอนามัยของมนุษย์และสิ่งแวดล้อมจากสารมลพิษตกค้างยาวนาน เช่น สารเคมีกําจัดศัตรูพืชบางชนิด"],"explanation_image":"assets/real-social-explanations/q040.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 40 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-041","subject":"social","question_number":41,"question_text":"นโยบายการเงินควบคุมโดยหน่วยงานใด (อก.58)","choices":{"A":"นายกรัฐมนตรี","B":"กระทรวงการคลัง","C":"รองนายกรัฐมนตรี","D":"ธนาคารแห่งประเทศไทย"},"correct_answer":"D","source_answer":"D. ธนาคารแห่งประเทศไทย","explanation_th":["ธนาคารแห่งประเทศไทย มีหน่าที่หลักในการดูแลนโยบายการเงิน เช่น การควบคุมปริมาณเงินในระบบ และการ กําหนดอัตราดอกเบี้ยนโยบาย เพื่อรักษาเสถียรภาพทางเศรษฐกิจ อธิบายตัวเลือกอื่น ดังนี้ 1) นายกรัฐมนตรี เป็นหัวหน้ำฝ่ายบริหาร กําหนดนโยบายภาพรวมของประเทศ 2) กระทรวงการคลังมีหน้ำที่ดูแลนโยบายการคลัง เช่น การจัดเก็บภาษี และการใช้จ่ายงบประมาณของรัฐ (ข้อนี้มักนำมาออกเป็นตัวลวง) 3) รองนายกรัฐมนตรี ปฏิบัติหน้ำที่ช่วยบริหารราชการตามที่นายกฯ มอบหมาย"],"explanation_image":"assets/real-social-explanations/q041.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2558,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 41 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-042","subject":"social","question_number":42,"question_text":"ข้อใดไม่่สัมพันธ์กัน (ปป.69)","choices":{"A":"ก๊าซคาร์บอนได้ออกไซด์ — การเผาป่าและใช้เชื้อเพลิงฟอสซิล","B":"ก๊าซมีเทน — การทำนาข้าวที่มีน้ำขังและการปศุสัตว์","C":"สารคลอโรฟลูออโรคาร์บอน — เครื่องปรับอากาศและอุตสาหกรรมทำความเย็น","D":"ก๊าซไนตรัสออกไซด์ — โรงงานอุตสาหกรรมและท่อไอเสียรถยนต์"},"correct_answer":"D","source_answer":"D. ก๊าซไนตรัสออกไซด์ — โรงงานอุตสาหกรรมและท่อไอเสียรถยนต์","explanation_th":["ก๊าซไนตรัสออกไซด์ - โรงงานอุตสาหกรรมและท่อไอเสียรถยนต์ เป็นคู่ที่ไม่่สัมพันธ์กันอย่างชัดเจนที่สุดในบริบทของ ก๊าซเรือนกระจก เพราะแหล่งกําเนิดหลักของก๊าซไนตรัสออกไซด์ Ao ภาคการเกษตร ส่วนควันจากท่อไอเสียรถยนต์มักจะเป็น ก๊าซคาร์บอนมอนอกไซต์ หรือออกไซด์ของไนโตรเจนที่ทำให้เกิดผุ่นควันและฝนกรดมากกว่า อธิบายตัวเลือกอื่น ดังนี้ 1) ก๊าซคาร์บอนได้ออกไซต์ สัมพันธ์กับการเผาป่าและการใช้เชื้อเพลิงฟอสซิลอย่างถูกต้อง 2) ก้าซมีเทน สัมพันธ์กับการทำนาข้าวที่มีน้้าขังและการปศุสัตว์ 3) สารคลอโรฟลูออโรคาร์บอน สัมพันธ์กับอุตสาหกรรมทำความเย็นและเครื่องปรับอากาศ ss"],"explanation_image":"assets/real-social-explanations/q042.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 42 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-043","subject":"social","question_number":43,"question_text":"เรไรเป็นหัวหน้ำที่ใช้การประนีประนอมในการทำงานและแก้ปัญหาความขัดแย้งร่วมกับผู้อื่นได้้เป็นอย่างดี พฤติกรรมของเรไรตรงกับรูปแบบการจัดการความขัดแย้งข้อใด","choices":{"A":"Competing","B":"Avoiding","C":"Compromising","D":"Accommodating"},"correct_answer":"C","source_answer":"C. Compromising","explanation_th":["Compromising (การประนีประนอม) คือการจัดการความขัดแย้งโดยที่ทั้งสองฝ่ายยอมถอยคนละก้าว เสียสละบางส่วนเพื่อให้ตกลงกันได้้และได้้ประโยชน์ร่วมกันในระดับที่ยอมรับได้้ อธิบายตัวเลือกอื่น ดังนี้ 1) Competing (การแข่งขัน/การเอาชนะ) คือการยึดเบ้าหมายตนเองเป็นใหญ่ ไม่่สนใจความต้องการของผู้อื่น (หกก“๒๐5๑) 2) Avoiding (การหลีกเลี่ยง) คือการหนีปัญหา ไม่่เผชิญหน้ำกับความขัดแย้ง (Lose-Lose) 4) Accommodating (การยอมตาม) คือการยอมโอนอ่อนผ่อนตามผู้อื่น ยอมเสียสละความต้องการของตนเองเพื่อรักษา ความสัมพันธ์ (Lose-Win)"],"explanation_image":"assets/real-social-explanations/q043.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 43 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-044","subject":"social","question_number":44,"question_text":"ข้อใดต่อไปนี้เป็นตลาดผูกขาด","choices":{"A":"ไฟฟ้า","B":"เสื้อผ้า","C":"น้ำอัดลม","D":"สินค้าเกษตร"},"correct_answer":"A","source_answer":"A. ไฟฟ้า","explanation_th":["ไฟฟ้า เป็นสินค้าและบริการที่อยู่ในตลาดผูกขาด เนื่องจากมีผู้ผลิตและผู้ขายเพียงรายเดียว (ในไทยคือหน่วยงาน รัฐวิสาหกิจ เช่น กฟผ. กพ่น. กฟภ.) และไม่่มีสินค้าอื่นมาทดแทนได้้โดยตรง อธิบายตัวเลือกอื่น ดังนี้ 2) เสื้อผ้า จัดอยู่ในตลาดกึ่งแข่งขันกึ่งผูกขาด มีผู้ขายมาก สินค้าคล้ายกันแต่มีเอกลักษณ์ต่างกัน 3) น้้าอัดลม จัดอยู่ในตลาดผู้ขายน้อยราย มีบริษัทยักษ์ใหญ่ครองตลาดอยู่เพียงไม่่กี่ราย 4) สินค้าเกษตร จัดอยู่ในตลาดแข่งขันสมบูรณ์ มีผู้ซื้อและผู้ขายจำนวนมาก สินค้าเหมือนกันทุกประการ"],"explanation_image":"assets/real-social-explanations/q044.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 44 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-045","subject":"social","question_number":45,"question_text":"บิดาแห่งสหกรณ์โลกตรงกับข้อใด","choices":{"A":"มาร์ติน ลูเทอร์","B":"โรเบิร์ต โอเว่น","C":"ทอมัส เจฟเฟอร์สัน","D":"พระยามโนปกรณ์นิติธาดา"},"correct_answer":"B","source_answer":"B. โรเบิร์ต โอเว่น","explanation_th":["โรเบิร์ต โอเว่น ได้้รับการยกย่องให้เป็นบิดาแห่งการสหกรณ์โลก เนื่องจากเป็นผู้ริเริ่มแนวคิดและก่อตั้งร้านสหกรณ์ เพื่อช่วยเหลือคนงานในโรงงานของเขา ซึ่งเป็นรากฐานของขบวนการสหกรณ์ที่ประสบความสําเร็จ อธิบายตัวเลือกอื่น ดังนี้ 1) มาร์ติน ลูเทอร์ เป็นผู้นำการปฏิรูปศาสนาคริสต์นิกายโปรเตสแตนต์ ไม่ได้้เกี่ยวข้องกับสหกรณ์ 3) ทอมัส เจฟเฟอร์สัน เป็นประธานาธิบดีคนที่ 3 ของสหรัฐอเมริกา และผู้เขียนคำประกาศอิสรภาพสหรัฐอเมริกา 4) พระยามโนปกรณ์นิติธาดา เป็นนายกรัฐมนตรีคนแรกของประเทศไทย"],"explanation_image":"assets/real-social-explanations/q045.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 45 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-046","subject":"social","question_number":46,"question_text":"บทสวดแผ่เมตตาที่กล่าวว่า ‘อะนีฆา โหนตุ’ มีความหมายตรงกับข้อใด (ปป.69)","choices":{"A":"อย่าได้้มีเวรแก่กันและกันเลย","B":"อย่าได้้พยาบาทเบียดเบียนซึ่งกันและกันเลย","C":"อย่าได้้มีความทุกข์กายทุกข์ใจเลย","D":"จงมีความสุขกายสุขใจ รักษาตนให้พ้นจากทุกข์ภัยเถิด"},"correct_answer":"C","source_answer":"C. อย่าได้้มีความทุกข์กายทุกข์ใจเลย","explanation_th":["อย่าได้้มีความทุกข์กายทุกข์ใจเลย คำว่า อะนีฆา แปลว่า ไม่่มีความทุกข์กายทุกข์ใจ เป็นท่อนหนึ่งในบทสวด แผ่เมตตาให้แก่สรรพสัตว์เพื่อให้พันจากความลําบาก อธิบายตัวเลือกอื่น Mall 1) อย่าได้้มีเวรแก่กันและกันเลย ตรงกับคำสวดที่ว่า อะเวรา โหนตุ 2) อย่าได้้พยาบาทเบียดเบียนซึ่งกันและกันเลย ตรงกับคำสวดที่ว่า อัพยาบัชณา โหนตุ 4) จงมีความสุขกายสุขใจ รักษาตนให้พันจากทุกข์ภัยเถิด ตรงกับคำสวดที่ว่า สุขี อัตตานัง ปะริหะรันตุ OE"],"explanation_image":"assets/real-social-explanations/q046.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 46 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-047","subject":"social","question_number":47,"question_text":"สาราณียธรรม 6 เป็นหลักธรรมที่มุ่งเน้นเรื่องใดมากที่สุด (ปป.69)","choices":{"A":"ความกตัญญูกตเวที","B":"ความเมตตากรุณา","C":"ความสามัคคี","D":"ความสันโดษ"},"correct_answer":"C","source_answer":"C. ความสามัคคี","explanation_th":["ความสามัคคี สาราณียธรรม 6 คือ ธรรมที่เป็นเหตุให้ระลึกถึงกัน สร้างความรัก ความเคารพ และเกื้อกูลกัน เป็นหลักธรรมสำคัญที่ช่วยสร้างความสามัคคี ให้เกิดขึ้นในหมู่คณะ ลดความขัดแย้ง อธิบายตัวเลือกอื่น ดังนี้ 1) ความกตัญญกตเวที เป็นหลักธรรมเกี่ยวกับการรู้คุณและตอบแทนคุณ 2) ความเมตตากรุณา เป็นส่วนหนึ่งของพรหมวิหาร 4 เน้นความปรารถนาดีและอยากให้ผู้อื่นพันทุกข์ 4) ความสันโดษ เป็นหลักธรรมเกี่ยวกับการยินดีในสิ่งที่ตนมี เลี้ยงง่าย ไม่่เบียดเบียนผู้อื่น"],"explanation_image":"assets/real-social-explanations/q047.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 47 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-048","subject":"social","question_number":48,"question_text":"หลักธรรมที่ผู้บริหารหรือผู้ปกครองต้องมีคือข้อใด (ปป.61)","choices":{"A":"อริยสัจ 4","B":"พรหมวิหาร 4","C":"สังคหวัตถุ 4","D":"อิทธิบาท 4"},"correct_answer":"B","source_answer":"B. พรหมวิหาร 4","explanation_th":["พรหมวิหาร 4 (เมตตา กรุณา มุทิตา อุเบกขา) ถือเป็นธรรมของผู้ใหญ่หรือผู้บริหารที่ต้องใช้ในการปกครองดูแล ผู้น้อยให้มีความสุข ให้ความช่วยเหลือ ให้การสนับสนุน และวางตัวเป็นกลางอย่างยุติธรรม อธิบายตัวเลือกอื่น ดังนี้ 1) อริยสัจ 4 คือ หลักความจริงอันประเสริฐ 4 ประการ สําหรับใช้เป็นกระบวนการแก้ปัญหาทุกอย่างในชีวิต 3) สังคหวัตถุ 4 Ao หลักธรรมสําหรับยึดเหนี่ยวจิตใจผู้อื่น (ทาน ปิยวาจา อัตถจริยา สมานัตตตา) มักใช้ในการเข้าสังคมหรือ ทำงานรวมกับเพื่อนรวมงาน 4) อิทธิบาท 4 fo หลักธรรมเพื่อมุงสูความสําเร็จในการทำงานหรือการเรียน (ฉันทะ วิริยะ จิตตะ วิมังสา)"],"explanation_image":"assets/real-social-explanations/q048.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2561,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 48 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-049","subject":"social","question_number":49,"question_text":"การที่จะเป็นตำรวจที่ดี ต้องมีหลักธรรมในข้อใด (ปป.66)","choices":{"A":"ขันธ์ 5","B":"ไตรสิกขา","C":"อริยสัจ 4","D":"ไตรลักษณ์"},"correct_answer":"B","source_answer":"B. ไตรสิกขา","explanation_th":["ไตรสิกขา ประกอบด้วย ศีล (การรักษากายวาจาให้อยู่ในระเบียบวินัย) สมาธิ (ความตั้งใจมั่น มีสติในการปฏิบัติ หน้ำที่) และบัญญา (ความรอบรู้ ใช้เหตุผลและวิจารณญาณในการแก้ปัญหา) ซึ่งเป็นข้อปฏิบัติพื้นฐานที่ตำรวจที่ดีต้องใช้ในการ ครองตนและปฏิบัติงาน อธิบายตัวเลือกอื่น ดังนี้ 1) ขันธ์ 5 คือ องค์ประกอบของชีวิตมบุษย์ (รูป เวทนา สัญญา สังขาร วิญญาณ) 3) อริยสัจ 4 คือ ความจริงสําหรับการแก้ปัญหา (ทุกข์ สมุทัย นิโรธ มรรค) 4) ไตรลักษณ์ คือ กฎธรรมชาติของสรรหสิ่งว่า ไม่่เที่ยง (อนิจจัง ทุกขัง อนัตตา)"],"explanation_image":"assets/real-social-explanations/q049.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 49 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-050","subject":"social","question_number":50,"question_text":"เมื่อถูกหัวหน้ำดุเพราะไปทำงานสาย แล้วหาวิธีปรับปรุงตนจนหัวหน้ำไม่่ดุ การกระทำดังกล่าวตรงกับหลักธรรมใด (ปป.68)","choices":{"A":"ทุกข์","B":"สมุทัย","C":"นิโรธ","D":"มรรค"},"correct_answer":"D","source_answer":"D. มรรค","explanation_th":["มรรค ในหลักอริยสัจ 4 มรรค fo หนทางหรือวิธีการปฏิบัติเพื่อนำไปสู่การดับทุกข์ การลงมือ หาวิธีปรับปรุงตัว จึงเปรียบเสมือนการลงมือปฏิบัติเพื่อแก้ปัญหาที่ต้นเหตุ อธิบายตัวเลือกอื่น ดังนี้ 1) ทุกข์ คือ ปัญหาที่เกิดขึ้น (ในสถานการณ์นี้คือ การโดนหัวหน้ำดุ ทำให้เกิดความไม่่สบายใจ) 2) สมุทัย คือ สาเหตุแห่งทุกข์ (ไนสถานการณ์นี้คือ การไปทำงานสาย) 3) นิโรธ คือ ความดับทุกข์หรือเป้าหมายที่ต้องการ (ในสถานการณ์นี้คือ การที่หัวหน้ำเลิกดุแล้ว) โยลย้ณีจง๐ไฟ ่้นอณญณษณญ่้อลวรวกวไรกวงาีวาวีว วนนโนโนนววไ"],"explanation_image":"assets/real-social-explanations/q050.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 50 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-051","subject":"social","question_number":51,"question_text":"คนที่เชื่อมั่นในสิ่งงมงายโดยไม่่มีเหตุผล ตรงกับหลักอุปาทาน 4 ข้อใด (ตม.66)","choices":{"A":"กามุปาทาน","B":"สีลัพพตุปาทาน","C":"ทิฏฐุปาทาน","D":"อัตตวาทุปาทาน"},"correct_answer":"B","source_answer":"B. สีลัพพตุปาทาน","explanation_th":["สีลัพพตุปาทาน คือ ความยึดมั่นถือมั่นในศีลและพรต ข้อปฏิบัติ พิธีกรรม หรือความเชื่อทางไสยศาสตร์ที่งมงาย โดยเชื่อว่าจะทำให้ตนบริสุทธิ์หรือหลุดพันได้้โดยไม่่มีเหตุผลรองรับ อธิบายตัวเลือกอื่น ดังนี้ 1) กามุปาทาน คือ ความยืดมั่นถือมั่นในกามารมณ์ที่น่าใคร่น่าพอใจ 3) ทิฏฐปาทาน Ao ความยึดมั่นถือมั่นในทิฏฐิ หรือลัทธิความเชื่อ ทฤษฎี แนวความคิดของตนเองเป็นใหญ่ 4) อัตตวาทุปาทาน คือ ความยืดมั่นถือมั่นในวาทะว่ามีตัวมีตน"],"explanation_image":"assets/real-social-explanations/q051.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 51 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-052","subject":"social","question_number":52,"question_text":"เขียวกับขาวเป็นเพื่อนกัน ช่วยเหลือกัน ตรงกับทิศ 6 ในข้อใด (ปป.69)","choices":{"A":"ทิศเบื้องซ้าย","B":"ทิศเบื้องขวา","C":"ทิศเบื้องล่าง","D":"ทิศเบื้องหลัง"},"correct_answer":"A","source_answer":"A. ทิศเบื้องซ้าย","explanation_th":["ทิศเบื้องข้าย (อุตตรทิส) ตามหลักทิศ 6 ในทางพระพุทธศาสนา ทิศเบื้องข้ายเปรียบเสมือน มิตรสหาย หรือเพื่อนฝูง ที่ต้องมีความรักใคร่ ช่วยเหลือเกื้อกูล และตักเดือนกันในยามประมาท อธิบายตัวเลือกอื่น ดังนี้ 2) ทิศเบื้องขวา (ทักชิณทิส) หมายถึง ครูบาอาจารย์ 3) ทิศเบื้องล่าง (เหฏฐิมทิส) หมายถึง ลูกจ้าง บริวาร หรือผู้ไต้บังคับบัญชา 4) ทิศเบื้องหลัง (ปัจฉิมทิส) หมายถึง ภรรยา anil หรือคู่ครอง (เสริมทิศที่เหลือ: ทิศเบื้องหน้ำ คือ พ่อแม่ และ ทิศเบื้องบน คือ สมณะพราหมณ์/พระสงซ์)"],"explanation_image":"assets/real-social-explanations/q052.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 52 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-053","subject":"social","question_number":53,"question_text":"ตำรวจที่ปฏิเสธการรับสินบนเพราะกลัวว่าจะถูกตั้งคณะกรรมการสอบสวนและถูกไล่ออก จัดว่ามีธรรมข้อใด","choices":{"A":"ขันติ","B":"โสรัจจะ","C":"โอตตัปปะ","D":"หิริิ"},"correct_answer":"C","source_answer":"C. โอตตัปปะ","explanation_th":["โอตตัปปะ (โอตตัปปะ) คือ ความเกรงกลัวต่อบาป หรือความหวาดกลัวต่อผลลัพธ์และบทลงโทษ ที่จะตามมาจาก การทำความผิด ในกรณีนี้คือการกลัวถูกสอบสวนและไล่ออก อธิบายตัวเลือกอื่น ดังนี้ 1) ขันติ คือ ความอดทนอดกลั้นต่อความยากลําบากและสิ่งยั๋วยุ 2) โสรัจจะ fo ความสงบเสงี่ยม การรักษากริยามารยาทให้งดงามเมื่อเผชิญเหตุการณ์ต่าง ๆ 4) หิริิ คือ ความละอายต่อบาป (เกิดจากจิตสํานึกภายในตนเองว่าสิ่งนั้นไม่่ดี จึงละอายที่จะทำ ไม่ได้้เกี่ยวกับความกลัว บทลงโทษ)"],"explanation_image":"assets/real-social-explanations/q053.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 53 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-054","subject":"social","question_number":54,"question_text":"พนักงานสอบสวนรีบสรุปสำนวนส่งฟ้องผู้ต้องหาเพียงเพราะผู้ต้องหาเคยมีปากเสียงกับตนมาก่อน เข้าข่ายอคติในข้อใด","choices":{"A":"ฉันทาคติ","B":"ภยาคติ","C":"โมหาคติ","D":"โทสาคติ"},"correct_answer":"D","source_answer":"D. โทสาคติ","explanation_th":["'โทสาศติ คือ ความลําเอียงเพราะความโกรธ เกลียด ขัง หรือมีความบาดหมางขัดเคืองใจกันมาก่อน ทำให้ตัดสินใจ ลงโทษหรือปฏิบัติหน้ำที่อย่างไม่่เป็นธรรม อธิบายตัวเลือกอื่น ดังนี้ 1) ฉันทาคติ Ao ความลําเอียงเพราะความรัก ความชอบพอ หรือความสนิทสนม 2) ภยาคติ คือ ความลําเอียงเพราะความกลัว (เช่น กลัวอิทธิพลของผู้มีอํานาจ) 3) โมหาศติ คือ ความลําเอียงเพราะความหลง เขลา ขาดบัญญา หรือได้้รับข้อมูลมาไม่่ครบถ้วน โยลย้ณีจง๐ไฟ ่้นอณญณษณญ่้อลวรวกวไรกวงาีวาวีว วนนโนโนนววไ"],"explanation_image":"assets/real-social-explanations/q054.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 54 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-055","subject":"social","question_number":55,"question_text":"การนำหลักโภควิภาค 4 มาใช้ จะช่วยแก้ปัญหาใดในสังคมของข้าราชการตำรวจ","choices":{"A":"ปัญหาหนี้สินล้นพ้นตัวและการทุจริตคอร์รัปชัน","B":"ปัญหาความเครียดจากการทำงานหนัก","C":"ปัญหาการขาดความรู้ด้านเทคโนโลยี","D":"ปัญหาความขัดแย้งกับผู้บังคับบัญชา"},"correct_answer":"A","source_answer":"A. ปัญหาหนี้สินล้นพ้นตัวและการทุจริตคอร์รัปชัน","explanation_th":["ปัญหาหนี้สินล้นพันตัวและการทุจริตคอร์รัปชัน หลักโภควิภาค 4 คือหลักการจัดสรรทรัพย์สิน (แบ่งรายได้้เป็น 4 ส่วน โดย 1 ส่วนใช้จ่ายเลี้ยงซีพ, 2 ส่วนใช้ลงทุนประกอบอาชีพ, 1 ส่วนเก็บออมไว้ใช้ยามจำเป็น) ซึ่งเป็นหลักการบริหารการเงินที่ช่วยป้องกันการใช้จ่ายเกินตัว อันเป็นต้นเหตุของปัญหาหนี้สินและการหาเงินในทางทุจริต อธิบายตัวเลือกอื่น Mail 2) ปัญหาความเครียดจากการทำงานหนัก ควรใช้หลักธรรมหมวดอื่น ๆ เช่น พรหมวิหาร 4 หรือ อิทธิบาท 4 3) ปัญหาการขาดความรู้ด้านเทคโนโลยี ไม่่เกี่ยวข้องกับหลักโภควิภาค 4 ซึ่งเป็นเรื่องการเงิน 4) ปัญหาความขัดแย้งกับผู้บังคับบัญชา ควรใช้หลัก สาราณียธรรม 6 หรือ ทิศ 6 ในการแก้ปัญหาความสัมพันธ์"],"explanation_image":"assets/real-social-explanations/q055.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 55 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-056","subject":"social","question_number":56,"question_text":"มรรคมีองค์ 8 เมื่อนำมาย่อและจัดกลุ่มแล้ว จะตรงกับหลักธรรมข้อใด","choices":{"A":"ไตรสิกขา","B":"อิทธิบาท 4","C":"สังคหวัตถุ 4","D":"พรหมวิหาร 4"},"correct_answer":"A","source_answer":"A. ไตรสิกขา","explanation_th":["'ไตรสิกขา มรรคมืองค์ 8 (หนทางสู่การดับทุกข์) เมื่อนำมาย่อและจัดหมวดหมู่แล้วจะได้้เป็น ไตรสิกขา (ศีล สมาธิ yyy) โดย สัมมาวาจา สัมมากัมมันตะ สัมมาอาชีวะ จัดอยู่ในหมวด Aa, สัมมาวายามะ สัมมาสติ สัมมาสมาธิ จัดอยู่ใน หมวด สมาธิ, และ สัมมาทิฏฐิ สัมมาสังกัปปะ จัดอยู่ในหมวด บปัญญา อธิบายตัวเลือกอื่น ดังนี้ 2) อิทธิบาท 4 fo หลักธรรมเพื่อความสําเร็จในการทำงาน (ฉันทะ วิริยะ จิตตะ วิมังสา) 3) สังคหวัตถุ 4 คือ หลักธรรมเพื่อการสงเคราะห์และยืดเหนี่ยวจิตใจผู้อื่น (ทาน ปิยวาจา อัตถจริยา สมานัตตตา) 4) พรหมวิหาร 4 คือ หลักธรรมสําหรับผู้ใหญ่หรือผู้ปกครอง (เมตตา กรุณา มุทิตา อุเบกขา)"],"explanation_image":"assets/real-social-explanations/q056.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 56 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-057","subject":"social","question_number":57,"question_text":"คุณธรรมที่ควรปลูกฝังในอาชีพตำรวจคือข้อใด (อก.60)","choices":{"A":"อริยสัจ 4","B":"อิทธิบาท 4","C":"สังคหวัตถุ 4","D":"พรหมวิหาร 4"},"correct_answer":"D","source_answer":"D. พรหมวิหาร 4","explanation_th":["'พรหมวิหาร 4 อาชีพตำรวจเป็นอาชีพที่ต้องดูแลทุกข์สุขของประชาชนและบังคับใช้กฎหมาย จึงต้องมีพรหมวิหาร 4 เป็นหลักประจำใจ fo มีความปรารถนาดีอยากให้ประชาชนมีความสุข (เมตตา) ช่วยเหลือเมื่อประชาชนตกทุกข์ได้้ยาก (กรุณา) ยินดีเมื่อผู้อื่นได้้ดี (มุทิตา) และที่สําคัที่สุดคือต้องมีความยุติธรรม วางตัวเป็นกลาง ไม่่เอนเอียง (อุเบกขา) อธิบายตัวเลือกอื่น ดังนี้ 1) อริยสัจ 4 คือ หลักความจริงอันประเสริฐเพื่อการแก้ปัญหาความทุกข์ 2) อิทธิบาท 4 คือ หลักธรรมที่ใช้เพื่อความมุ่งมั่นสู่ความสําเร็จในหน้ำที่การงาน 3) สังคหวัตถุ 4 เน้นไปที่การผูกมิตรและการเข้าสังคมเป็นหลัก โยลย้ณีจง๐ไฟ ่้นอณญณษณญ่้อลวรวกวไรกวงาีวาวีว วนนโนโนนววไ"],"explanation_image":"assets/real-social-explanations/q057.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2560,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 57 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-058","subject":"social","question_number":58,"question_text":"ถ้าทุกคนต้องการเป็นคนดีในสังคม ควรปฏิบัติตนตามหลักธรรมข้อใด","choices":{"A":"สัปปุริสธรรม 7","B":"สังคหวัตถุ 4","C":"อิทธิบาท 4","D":"นิพพาน"},"correct_answer":"A","source_answer":"A. สัปปุริสธรรม 7","explanation_th":["สัปปุริสธรรม 7 คือ ธรรมของสัตบุรุษ หรือธรรมของคนดี ประกอบด้วยหลัก 7 ประการ ที่สอนให้คนรู้จักเหตุ รู้จักผล รู้จักตน รู้จักประมาณ รู้จักกาลเวลา รู้จักชุมชน และรู้จักบุคคล หากทุกคนปฏิบัติได้้ตามนี้ สังคมจะมีความสงบสุขและ เป็นระเบียบเรียบร้อย อธิบายตัวเลือกอื่น Mall 2) สังคหวัตถุ 4 เป็นธรรมที่เน้นการสงเคราะห์หรือการอยู่ร่วมกันเพื่อสร้างมนุษยสัมพันธ์ 3) อิทธิบาท 4 เป็นธรรมที่เน้นความสําเร็จส่วนบุคคลในการเรียนหรือการทำงาน 4) นิพพาน เป็นเบ้าหมายสูงสุดทางพระพุทธศาสนาในการหลุดพ้นจากกิเลสและกองทุกข์ทั้งปวง ไม่่ใช่ข้อปฏิบัติทางสังคม 'โดยตรง"],"explanation_image":"assets/real-social-explanations/q058.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 58 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-059","subject":"social","question_number":59,"question_text":"ข้อใดคือความเพียรละบาปอกุศลธรรมที่เกิดขึ้นแล้ว (ปป.61)","choices":{"A":"สังวรปธาน","B":"ปหานปธาน","C":"ภาวนาปธาน","D":"อนุรักขนาปธาน"},"correct_answer":"B","source_answer":"B. ปหานปธาน","explanation_th":["ปหานปธาน ตามหลักปธาน 4 (ความเพียร 4 ประการ) ปหานปธาน คือความเพียรพยายามที่จะละทิ้งหรือกําจัด บาปอกุศล ความชั่ว หรือนิสัยไม่ดีต่าง ๆ ที่มันเกิดขึ้นมาแล้วในตัวเราให้หมดไป อธิบายตัวเลือกอื่น ดังนี้ 1) สังวรปธาน fo ความเพียรระวังไม่่ให้บาปหรือความชั่วที่ยังไม่่เกิด เกิดขึ้นมาได้้ 3) ภาวนาปธาน คือ ความเพียรสร้างสรรค์หรือทำกุศลความดีที่ยังไม่่เกิด ให้เกิดขึ้นมา 4) อนุรักขนาปธาน Ao ความเพียรรักษากุศลความตีที่เกิดขึ้นแล้ว ให้เจริญงอกงามอิ่ง ๆ ขึ้นไป"],"explanation_image":"assets/real-social-explanations/q059.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2561,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 59 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-060","subject":"social","question_number":60,"question_text":"เมื่อคนเราพากเพียรจนสามารถสอบติดแพทย์ได้้ ตรงกับหลักธรรมข้อใดในอิทธิบาท 4 (ปป.68)","choices":{"A":"วิริยะ","B":"ฉันทะ","C":"จิตตะ","D":"วิมังสา"},"correct_answer":"B","source_answer":"B. ฉันทะ","explanation_th":["60. เฉลย ข้อ 1. วิริยะ คีย์เวิร์ดในโจทย์คือคำว่าพากเพียร ซึ่งตรงกับคำว่าวิริยะ ในหลักอิทธิบาท 4 ที่แปลว่า ความเพียรพยายาม ความอดทนไม่่ย่อท้อต่ออุปสรรค จนกว่าจะบรรลุเบ้าหมาย (สอบติดแพทย์) อธิบายตัวเลือกอื่น ดังนี้ 2) dune คือ ความรัก ความพอใจ หรือความหลงใหลในลิ่งที่ทำ (เช่น มีใจรักอยากเป็นหมอ) 3) จิตตะ คือ ความเอาใจใส่ ผักใฝ่ จดจ่อกับสิ่งที่ทำ (เช่น ตั้งใจอ่านหนังสือสอบอย่างมีสมาธิ) 4) วิมังสา คือ การหมั่นตริตรอง ทบทวน และหาเหตุผล (เช่น การประเมินข้อผิดพลาดจากการทำข้อสอบเก่าแล้วนำมา ปรับปรุง) ชรชรโญไ ป"],"explanation_image":"assets/real-social-explanations/q060.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 60 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-061","subject":"social","question_number":61,"question_text":"เหตุการณ์การเกิดพระอริยสงฆ์องค์แรกตรงกับวันใด","choices":{"A":"วันมาฆบูชา","B":"วันอัฐมีบูชา","C":"วันวิสาขบูชา","D":"วันอาสาฬหบูชา"},"correct_answer":"D","source_answer":"D. วันอาสาฬหบูชา","explanation_th":["วันอาสาหหบูชา เป็นวันที่พระพุทธเจ้าทรงแสดงปฐมเทศนา (ธัมมจักกัปปวัตตนสูตร) โปรดบัญจวัคคีย์ ทำให้ ท่านอัญญาโกณฑัญญะ ได้้ดวงตาเห็นธรรมและขอบวชเป็นพระอริยสงฆ์สาวกองค์แรกในพระพุทธศาสนา ส่งผลให้เหตุการณ์ ในวันนั้นมีพระรัตนตรัยครบองค์ 3 (พระพุทธ พระธรรม พระสงข์) อย่างสมบูรณ์เป็นครั้งแรก อธิบายตัวเลือกอื่น ดังนี้ 1) วันมาฆบูชา คือวันที่มีการจาตุรงคสันนิบาต (พระสงฆ์ 1,250 รูปมาประชุมกันโดยมีได้้นัดหมาย) 2 วันอัฐมีบูชา คือวันถวายพระเพลิงพระบรมศพของพระพุทธเจ้า (หลังวันวิสาขบูชา 8 วัน) 3) วันวิสาขบูชา คือวันประสูติ ตรัสรู้ และปรินิพพาน"],"explanation_image":"assets/real-social-explanations/q061.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 61 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-062","subject":"social","question_number":62,"question_text":"วันสำคัญทางพุทธศาสนาในข้อใดไม่่มีกิจกรรมเวียนเทียน (อก.58)","choices":{"A":"วันมาฆบูชา","B":"วันวิสาขบูชา","C":"วันออกพรรษา","D":"วันอาสาฬหบูชา"},"correct_answer":"C","source_answer":"C. วันออกพรรษา","explanation_th":["วันออกพรรษา โดยธรรมเนียมปฏิบัติของไทย กิจกรรมหลักในวันออกพรรษาคือการทำบุญตักบาตรเทโวโรหณะ ฟังเทศน์พังธรรม และประเพณีท่องถิ่น (เช่น ไหลเรือไฟ รับบัว) แต่จะไม่่มีการจัดพิธีเวียนเทียนในตอนคำเหมือนวันสำคัญ สากลอื่น ๆ อธิบายตัวเลือกอื่น ดังนี้ 1) วันมาฆบูชา มีการเวียนเทียน 2) วันวิสาขนูชา มีการเวียนเทียน 4) วันอาสาฬหบูชา มีการเวียนเทียน (และในบางวัดอาจมีการเวียนเทียนในวันอัฐมีบูชาด้วย)"],"explanation_image":"assets/real-social-explanations/q062.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2558,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 62 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-063","subject":"social","question_number":63,"question_text":"ในวันมาฆบูชา พระพุทธเจ้าได้้ทรงแสดงหลักธรรมที่เป็นเสมือนหัวใจของพระพุทธศาสนา หลักธรรมนั้นคือข้อใด","choices":{"A":"อริยสัจ 4","B":"โอวาทปาติโมกข์","C":"ธัมมจักกัปปวัตตนสูตร","D":"อิทธิบาท 4"},"correct_answer":"B","source_answer":"B. โอวาทปาติโมกข์","explanation_th":["โอวาทปาติโมกข์ คือหลักธรรมที่เป็นหัวใจสำคัญของพระพุทธศาสนา 3 ประการ ได้้แก่ 1. การไม่่ทำบาปทั้งปวง 2 การทำกุศลให้ถึงพร้อม (ทำความดี) 3. การทำจิตใจให้บริสุทธิ์ผ่องใส ซึ่งพระพุทธองค์ทรงแสดงแก่พระอรหันต์ 1,250 รูป ที่มาประชุมกันในวันมาฆบูชา อธิบายตัวเลือกอื่น ดังนี้ 1) อริยสัจ 4 คือ ความจริงอันประเสริฐเพื่อการดับทุกข์ (พระพุทธเจ้าตรัสรู้ด้วยหลักธรรมนี้) 3) ธัมมจักกัปปวัตตนสูตร Ao ปฐมเทศนากัณฑ์แรก ที่ทรงแสดงในวันอาสาฬหนูชา 4) อิทธิบาท 4 Aa หลักธรรมเพื่อความสําเร็จในการทำงาน ชรชรโญไ ป"],"explanation_image":"assets/real-social-explanations/q063.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 63 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-064","subject":"social","question_number":64,"question_text":"วันพระเจ้าเปิดโลกตรงกับวันใด","choices":{"A":"วันธรรมสวนะ","B":"วันเข้าพรรษา","C":"วันเทโวโรหณะ","D":"วันออกพรรษา"},"correct_answer":"C","source_answer":"C. วันเทโวโรหณะ","explanation_th":["วันเทโวโรหณะ (ตรงกับวันแรม 1 คำ เดือน 11 หรือหลังวันออกพรรษา 1 วัน) เป็นวันที่พระพุทธเจ้าเสด็จลงจาก สวรรค์ชั้นดาวดีงส์หลังจากการโปรดพระพุทธมารดา ตํานานกล่าวว่าในวันนั้นพระพุทธองค์ทรงแสดงปาฏิหาริย์เปิดโลกทั้ง 3 (สวรรค์ มนุษย์ นรก) ให้สามารถมองเห็นซึ่งกันและกันได้้ จึงเรียกวันนี้อีกชื่อหนึ่งว่าวันพระเจ้าเปิดโลก อธิบายตัวเลือกอื่น ดังนี้ 1) วันธรรมสวนะ คือ วันพระปกติ (วันขึ้น/แรม 8 คำ uae 15 คำ ของทุกเดือน) 2) วันเข้าพรรษา คือ วันแรม 1 คำ เดือน 8 (พระสงฆ์เริ่มจำพรรษา 3 เดือน) 4) วันออกพรรษา คือ วันขึ้น 15 คำ เดือน 11 (วันสิ้นสุดการจำพรรษา ซึ่งเกิดก่อนวันเทโวโรหณะ 1 วัน)"],"explanation_image":"assets/real-social-explanations/q064.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 64 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-065","subject":"social","question_number":65,"question_text":"วันสำคัญทางพุทธศาสนาที่องค์การสหประชาชาติรับรองให้เป็นวันสำคัญสากลคือวันใด (อก.58)","choices":{"A":"วันมาฆบูชา","B":"วันวิสาขบูชา","C":"วันเข้าพรรษา","D":"วันอาสาฬหบูชา"},"correct_answer":"B","source_answer":"B. วันวิสาขบูชา","explanation_th":["วันวิสาขบูชา องค์การสหประชาชาติ (UN) ได้้มีมติรับรองให้วันวิสาขบูชาเป็นวันสำคัญสากลของโลก เมื่อปี พ.ศ. 2542 (ค.ศ. 1999) เนื่องจากเป็นวันที่เกิดเหตุการณ์สำคัญที่สุดของพระพุทธศาสนา คือ ประสูติ ตรัสรู้ และปรินิพพาน และเพื่อยกย่องพระพุทธเจ้าในฐานะมหาบุรุษผู้ให้ความสำคัญกับสันติภาพและความเมตตาต่อเพื่อนมนุษย์ อธิบายตัวเลือกอื่น ดังนี้ 1) 3) และ 4) เป็นวันสำคัญทางพุทธศาสนาในประเทศไทยและประเทศที่นับถือศาสนาพุทธ แต่ไม่ได้้ถูกประกาศเป็นวันสำคัญ ระดับสากลของโลกโดยสหประชาชาติ"],"explanation_image":"assets/real-social-explanations/q065.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2558,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 65 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-066","subject":"social","question_number":66,"question_text":"วันที่อนุญาตให้พระสงฆ์ว่ากล่าวตักเตือนกันได้้เรียกว่าวันอะไร","choices":{"A":"วันธรรมสวนะ","B":"วันเข้าพรรษา","C":"วันมาฆบูชา","D":"วันมหาปวารณา"},"correct_answer":"D","source_answer":"D. วันมหาปวารณา","explanation_th":["วันมหาปวารณา (ตรงกับวันออกพรรษา ขึ้น 15 คำ เดือน 11) เป็นวันที่พระสงฆ์ทำพิธีปวารณาแทนการสวด ปาฏิโมกข์ คือการเปิดโอกาสให้พระภิกษุด้วยกันสามารถว่ากล่าวตักเดือน ชี้แนะข้อบกพร่องของกันและกันได้้ด้วยจิตเมตตา เพื่อให้เกิดความบริสุทธิ์ในหมู่คณะ อธิบายตัวเลือกอื่น Mail 1) วันธรรมสวนะ คือ วันพระปกติที่มีการทำบุญและพฟังธรรม 2 วันเข้าพรรษา คือ วันเริ่มต้นการจำพรรษาของพระสงฆ์เป็นเวลา 3 เดือน ห้ามจาริกค้างแรมที่อื่น 3) วันมาฆบูชา คือ วันที่พระพุทธเจ้าทรงแสดงโอวาทปาติโมกข์"],"explanation_image":"assets/real-social-explanations/q066.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 66 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-067","subject":"social","question_number":67,"question_text":"วันธรรมสวนะปกติในหนึ่งเดือนมีกี่วัน","choices":{"A":"4 วัน","B":"2 วัน","C":"1 วัน","D":"7 วัน"},"correct_answer":"A","source_answer":"A. 4 วัน","explanation_th":["4 วัน วันธรรมสวนะ หรือที่เราเรียกติดปากว่าวันพระ ใน 1 เดือนทางจันทรคติจะมีกําหนดไว้ 4 วัน Yun วันขึ้น 8 คำ, วันขึ้น 15 คำ, วันแรม 8 eh และ วันแรม 15 Ah (หรือแรม 14 Ay ในกรณีที่เป็นเดือนขาด) อธิบายตัวเลือกอื่น ดังนี้ 2) 3) และ 4) เป็นจำนวนวันที่ไม่่ถูกต้องตามปฏิทินจันทรศติที่กําหนดไว้สําหรับวันพระ โยลย้ณีจง๐ไฟ ่้นอณญณษณญ่้อลวรวกวไรกวงาีวาวีว วนนโนโนนววไ"],"explanation_image":"assets/real-social-explanations/q067.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 67 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-068","subject":"social","question_number":68,"question_text":"วันมาฆบูชาเกิดขึ้นหลังจากพระพุทธเจ้าตรัสรู้แล้วเป็นเวลานานเท่าใด","choices":{"A":"7 เดือน","B":"3 เดือน","C":"9 เดือน","D":"1 ปี"},"correct_answer":"C","source_answer":"C. 9 เดือน","explanation_th":["9 เดือน ข้อนี้ใช้วิธีนับเดือน พระพุทธเจ้าตรัสรู้ในวันเพ็ญเดือน 6 (วันวิสาขบูชา) และเหตุการณ์จาตุรงคสันนิบาต (วันมาฆบูชา) เกิดขึ้นในวันเพ็ญเดือน 3 ของปีถัดมา เมื่อนับระยะเวลาจากเดือน 6 วนไปจนถึงเดือน 3 จึงมีระยะเวลาห่างกัน 9 เดือนพอดีครับ อธิบายตัวเลือกอื่น ดังนี้ 1) 2) และ 4) เป็นระยะเวลาที่ไม่่ถูกต้องตามประวัติศาสตร์พุทธกาล"],"explanation_image":"assets/real-social-explanations/q068.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 68 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-069","subject":"social","question_number":69,"question_text":"ข้อใดไม่่อยู่ในจาตุรงคสันนิบาต (ปป.58)","choices":{"A":"เป็นวันที่ดวงจันทร์เสวยมาฆฤกษ์","B":"พระสงฆ์เหล่านั้นเป็นพระอรหันต์ทั้งสิ้น","C":"พระสงฆ์ที่มาประชุมล้วนบรรลุระดับอนาคามี","D":"พระสงฆ์ 1,250 รูปมาประชุมกันโดยมิได้้นัดหมาย"},"correct_answer":"C","source_answer":"C. พระสงฆ์ที่มาประชุมล้วนบรรลุระดับอนาคามี","explanation_th":["พระสงฆ์ที่มาประชุมล้วนบรรลุระดับอนาคามี ข้อนี้ผิด เพราะองค์ประกอบที่ถูกต้องคือ พระสงฆ์ทั้ง 1.250 รูป ที่มาประชุมกันนั้นล้วนบรรลุธรรมเป็นพระอรหันต์ (ผู้หมดจดจากกิเลสโดยสิ้นเชิงและได้้อภิญญา 6) ไม่ใช่แค่ระดับพระ อนาคามี อธิบายตัวเลือกอื่น ดังนี้ 1) เป็นวันที่ดวงจันทร์เสวยมาขฤกษ์ (วันเพ็ญเดือน 3) เป็น 1 ใน 4 องค์ประกอบที่ถูกต้อง 2) พระสงฆ์เหล่านั้นเป็นพระอรหันต์ทั้งสิ้น เป็น 1 ใน 4 องค์ประกอบที่ถูกต้อง 4) พระสงฆ์ 1250 รูป มาประชุมกันโดยมีได้้นัดหมาย เป็น 1 ใน 4 องค์ประกอบที่ถูกต้อง"],"explanation_image":"assets/real-social-explanations/q069.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2558,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 69 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-070","subject":"social","question_number":70,"question_text":"การเวียนเทียนในวันสำคัญทางศาสนาต้องเวียนไปทางทิศใดและกี่รอบ","choices":{"A":"เวียนซ้ายทวนเข็มนาฬิกา 3 รอบ","B":"เวียนไปทางทิศใดก็ได้้ตามสะดวก 3 รอบ","C":"เวียนขวา 1 รอบ","D":"เวียนขวาตามเข็มนาฬิกา 3 รอบ"},"correct_answer":"D","source_answer":"D. เวียนขวาตามเข็มนาฬิกา 3 รอบ","explanation_th":["เวียนขวา ตามเข็มนาฬิกา 3 รอบ การเวียนเทียนในงานมงคลเรียกว่าการทำประทักษิณาวรรต คือการเดินเวียนขวา 'โดยให้สิ่งศักดิ์สิทธิ์ (เช่น โบสถ์ วิหาร หรือเจดีย์) อยู่ทางขวามือของเราเสมอ (ทิศตามเข็มนาฬิกา) จำนวน 3 รอบ เพื่อเป็นการ ระลึกถึงพระคุณของพระรัตนตรัยทั้ง 3 ประการ (พระพุทธ พระธรรม พระสงฆ์) อธิบายตัวเลือกอื่น ดังนี้ 1) เวียนข้าย ทวนเข็มนาฬิกา 3 รอบ การเวียนข้าย (อุตราวรรต) จะใช้ในงานอวมงคล เช่น การเดินเวียนศพรอบเมรุ 2) เวียนไปทางทิศใดก็ได้้ตามสะดวก 3 รอบ ผิดธรรมเนียมปฏิบัติของชาวพุทธ 3) เวียนขวา 1 รอบ จำนวนรอบไม่่ครบตามหลักการบูชาพระรัตนตรัย"],"explanation_image":"assets/real-social-explanations/q070.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 70 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-071","subject":"social","question_number":71,"question_text":"บุคคลใดได้้รับการยกเว้นไม่่ต้องถือศีลอด","choices":{"A":"กรรมกรที่ทำงานหนัก","B":"หญิงที่มีประจำเดือน","C":"ชายที่ช่วยภรรยาเลี้ยงลูก","D":"ผู้ประกอบอาชีพค้าขาย"},"correct_answer":"B","source_answer":"B. หญิงที่มีประจำเดือน","explanation_th":["หญิงที่มีประจำเดือน ตามหลักศาสนาอิสลาม การถือศีลอดในเดือนรอมฏอนเป็นข้อบังคับ แต่มีข้อยกเว้นให้กับ บุคคลบางกลุ่ม เช่น quae ผู้ที่เดินทางไกล สตรีมีครรภ์ สตรีให้นมบุตร คนซรา และ หญิงที่มีประจำเดือนหรือมีเลือดหลัง คลอด (แต่กลุ่มสตรีที่มีประจำเดือนจะต้องไปถือศีลอดชดเชยในภายหลังเมื่อร่างกายพร้อม) อธิบายตัวเลือกอื่น ดังนี้ 1) กรรมกรที่ทำงานหนัก ไม่่ได้้รับการยกเว้นโดยตรงตามหลักศาสนา เว้นแต่การทำงานนั้นจะทำให้เจ็บป่วยหรือเป็นอันตราย ถึงชีวิต 3) ขายที่ช่วยภรรยาเลี้ยงลูก ไม่่ใช่เงื่อนไขในการยกเว้นการถือศีลอด 4) ผู้ที่ประกอบอาชีพค้าขาย ไม่่ใช่เงื่อนไขในการยกเว้นการถือศีลอด OE"],"explanation_image":"assets/real-social-explanations/q071.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 71 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-072","subject":"social","question_number":72,"question_text":"วันอีสเตอร์ในศาสนาคริสต์จัดขึ้นเพื่อระลึกถึงเหตุการณ์ใด","choices":{"A":"การประสูติของพระเยซู","B":"การรับศีลล้างบาปครั้งแรก","C":"การเสวยพระกระยาหารมื้อสุดท้าย","D":"การฟื้นคืนพระชนม์ของพระเยซู"},"correct_answer":"D","source_answer":"D. การฟื้นคืนพระชนม์ของพระเยซู","explanation_th":["การพื้นคืนพระชนม์ของพระเยซู วันอีสเตอร์ เป็นวันเฉลิมฉลองการพื้นคืนชีพของพระเยชูคริสต์หลังจากที่ทรงถูกตรึง กางเขนและสิ้นพระชนม์ไปแล้ว 3 วัน ถือเป็นวันเฉลิมฉลองที่สำคัญที่สุดในศาสนาคริสต์ อธิบายตัวเลือกอื่น ดังนี้ 1) การประสูติของพระเขชู คือ วันคริสต์มาส 2) การรับศีลล้างบาปครั้งแรก เป็นพิธีกรรมทางศาสนา ไม่ใช่วันอีสเตอร์ 3) การเสวยพระกระยาหารมื้อสุดท้าย คือ วันพฤหัสบดีศักดิ์สิทธิ์ซึ่งเป็นเหตุการณ์ก่อนการถูกตรึงกางเขน"],"explanation_image":"assets/real-social-explanations/q072.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 72 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-073","subject":"social","question_number":73,"question_text":"ฮาลาลมีความหมายตรงกับข้อใด","choices":{"A":"สะอาดและปลอดภัย","B":"สิ่งที่ต้องห้าม","C":"สิ่งที่ควรหลีกเลี่ยง","D":"สิ่งที่อนุมัติหรืออนุญาต"},"correct_answer":"D","source_answer":"D. สิ่งที่อนุมัติหรืออนุญาต","explanation_th":["สิ่งที่อนุมัติ หรืออนุญาต คำว่า ฮาลาล เป็นภาษาอาหรับ แปลว่า อนุมัติหรืออนุญาต หมายถึง สิ่งที่ศาสนาอิสลาม อนุมัติให้มุสลิมกระทำได้้ บริโภคได้้ หรือใช้ประโยชน์ได้้โดยไม่่ผิดหลักศาสนา อธิบายตัวเลือกอื่น ดังนี้ 1) สะอาดและปลอดภัย เป็นผลพลอยได้้และเป็นมาตรฐานร่วมของกระบวนการผลิตอาหารฮาลาล แต่ไม่่ใช่ความหมายแปล ตรงตัวทางศาสนา 2) สิ่งที่ต้องห้าม ตรงกับคำว่าฮารอม ซึ่งตรงข้ามกับฮาลาล เช่น เนื้อหมู เครื่องดื่มแอลกอฮอล์ 3) สิ่งที่ควรหลีกเลี่ยง ตรงกับคำว่ามักรูฮ คือสิ่งที่ศาสนาไม่่ส่งเสริมให้ทำ แต่ถ้าทำก็ไม่่ถึงกับเป็นบาป"],"explanation_image":"assets/real-social-explanations/q073.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 73 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-074","subject":"social","question_number":74,"question_text":"ผู้นำสูงสุดของมุสลิมในประเทศไทยคือใคร","choices":{"A":"พระสังฆราช","B":"จุฬาราชมนตรี","C":"พระอัลลอฮ์","D":"พระสันตะปาปา"},"correct_answer":"B","source_answer":"B. จุฬาราชมนตรี","explanation_th":["จุฬาราชมนตรี เป็นตําแหน่งผู้นำสูงสุดทางศาสนาอิสลามในประเทศไทย มีหน้ำที่ให้คำปรึกษาแก่ทางราชการ เกี่ยวกับกิจการศาสนาอิสลาม และเป็นผู้นำทางจิตวิญญาณของพี่น้องชาวไทยมุสลิม อธิบายตัวเลือกอื่น ดังนี้ 1) พระสังฆราช คือ ผู้นำสูงสุดทางศาสนาพุทธในประเทศไทย 3) พระอัลลอฮ์ คือ พระเจ้าองค์เดียวอันสูงสุดในศาสนาอิสลาม (ไม่่ใช่ผู้นำที่เป็นตัวแทนบุคคล) 4) พระสันตะปาปา คือ ผู้นำสูงสุดของศาสนาคริสต์ นิกายโรมันคาทอลิก"],"explanation_image":"assets/real-social-explanations/q074.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 74 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-075","subject":"social","question_number":75,"question_text":"ประชาชนในสามจังหวัดชายแดนภาคใต้ของไทยส่วนใหญ่นับถือศาสนาอิสลามนิกายใด","choices":{"A":"ซุนนี","B":"ชีอะห์","C":"คอวาริช","D":"วาฮาบี"},"correct_answer":"A","source_answer":"A. ซุนนี","explanation_th":["ขุนนี ชาวมุสลิมส่วนใหญ่ในประเทศไทย รวมถึงในพื้นที่สามจังหวัดชายแดนภาคใต้ (ยะลา บัตตานี นราธิวาส) นับถือศาสนาอิสลามนิกายขุนนี ซึ่งเป็นนิกายที่มีผู้นับถือมากที่สุดในโลกด้วย อธิบายตัวเลือกอื่น Mil 2) ขีอะห์ เป็นนิกายใหญ่อันดับสอง ผู้นับถือส่วนใหญ่อยู่ในประเทศอิหร่านและอิรัก (ในไทยมีอยู่เป็นชนกลุ่มน้อย) 3) คอวาริช เป็นกลุ่มหรือนิกายย่อยในหน้ำประวัติศาสตร์อิสลามยุคแรก 4) วาฮาบี ไม่่ใช่นิกายหลัก แต่เป็นแนวคิดหรือขบวนการพื้นฟูศาสนาแบบอนุรักษ์นิยมที่เกิดขึ้นในคาบสมุทรอาหรับ OE"],"explanation_image":"assets/real-social-explanations/q075.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":"หลายปี","exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 75 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-076","subject":"social","question_number":76,"question_text":"ศาสนาใดไม่่ได้้เกิดขึ้นในอินเดีย (ปป.68)","choices":{"A":"ศาสนาอิสลาม","B":"ศาสนาพุทธ","C":"ศาสนาซิกข์","D":"ศาสนาพราหมณ์-ฮินดู"},"correct_answer":"A","source_answer":"A. ศาสนาอิสลาม","explanation_th":["ศาสนาอิสลาม มีแหล่งกําเนิดในภูมิภาคตะวันออกกลาง (ดินแดนคาบสมุทรอาหรับ) ณ นครเมกกะ ประเทศชาอุดีอาระเบียในปัจจุบัน อธิบายตัวเลือกอื่น ดังนี้ 2) ศาสนาพุทธ ถือกําเนิดในชมพูทวีป (พื้นที่รอยต่อประเทศอินเดียและเนปาลในบัจจุบัน) 3) ศาสนาชิกข์ ถือกําเนิดในแคว้นบัญจาบ ทางตอนเหนือของประเทศอินเดีย 4) ศาสนาพราหมณ์-ฮินดู ถือกําเนิดในประเทศอินเดียและเป็นศาสนาที่เก่าแก่ที่สุดของดินแดนนี้"],"explanation_image":"assets/real-social-explanations/q076.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 76 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-077","subject":"social","question_number":77,"question_text":"การแสดงตนเป็นพุทธมามกะตรงกับศีลข้อใดของศาสนาคริสต์ (ปป.68)","choices":{"A":"ศีลกำลัง","B":"ศีลมหาสนิท","C":"ศีลล้างบาป","D":"ศีลเจิมคนไข้"},"correct_answer":"A","source_answer":"A. ศีลกำลัง","explanation_th":["ศีลกําลัง การแสดงตนเป็นพุทธมามกะคือการประกาศตนว่ายอมรับนับถือพระพุทธศาสนาเมื่อถึงวัยที่รู้ความ ซึ่งเทียบเคียงได้้กับศีลกําลังของศาสนาคริสต์ (นิกายคาทอลิก) ที่เป็นการตอกย้าความเชื่อและประกาศตนเป็นคริสต์ศาสนิกชน อย่างสมบูรณ์เมื่อเดิบโตขึ้น อธิบายตัวเลือกอื่น ดังนี้ 2) ศีลมหาสนิท คือพิธีรับศีลโดยการรับประทานขนมบังและเหล้าองุ่นเพื่อระลึกถึงพระเยซู 3) ศีลล้างบาป คือพิธีแรกรับเข้าเป็นคริสตชน (มักทำตั้งแต่แรกเกิดเพื่อล้างบาปกําเนิด ซึ่งเด็กยังไม่่สามารถตัดสินใจด้วย ตนเองได้้) 4) ศึลเจิมคนไข้ คือพิธีเจิมน้้ามันศักดิ์สิทธิ์ให้แก่ผู้ปวยหนักเพื่อโปรดประทานกําลังใจ"],"explanation_image":"assets/real-social-explanations/q077.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 77 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-078","subject":"social","question_number":78,"question_text":"ซะกาตตรงกับข้อใด (ปป.68)","choices":{"A":"การถือศีลอด","B":"ทานบังคับ","C":"ปฏิญาณตน","D":"พิธีสารท"},"correct_answer":"B","source_answer":"B. ทานบังคับ","explanation_th":["ทานบังคับ ซะกาต คือการบริจาคทานที่เป็นข้อบังคับ ตามหลักปฏิบัติ 5 ประการของศาสนาอิสลาม โดยมุสลิมที่มี ทรัพย์สินถึงเกณฑ์ที่กําหนดจะต้องนำทรัพย์สินส่วนหนึ่งไปแจกจ่ายให้แก่ผู้ยากไร้และผู้ที่มีสิทธิรับตามศาสนบัญญัติ เพื่อเป็น การขัดเกลาจิตใจไม่่ให้ยึดติดในทรัพย์ อธิบายตัวเลือกอื่น ดังนี้ 1) การถือศีลอด ตรงกับคำว่า ซอม หรือการถือศีลอดในเดือนรอมฏอน 3) ปฏิญาณตน ตรงกับคำว่า ชาฮาดะฮ์ (การปฏิญาณว่าไม่่มีพระเจ้าอื่นใดนอกจากอัลลอย์) 4) พิธีสารท เป็นพิธีกรรมทางความเชื่อของศาสนาพราหมณ์-ฮินดูและพุทธ ในการอุทิศส่วนกุศลให้บรรพบุรุษ"],"explanation_image":"assets/real-social-explanations/q078.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 78 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-079","subject":"social","question_number":79,"question_text":"ดาบคู่ในสัญลักษณ์ของศาสนาซิกข์มีความหมายตรงกับข้อใด (ปป.69)","choices":{"A":"ความเป็นอมตะและเป็นหนึ่งเดียวของพระเจ้า","B":"ความรู้แจ้งเห็นจริงในสัจธรรมและสติปัญญา","C":"ความสมัครสมานกลมเกลียวกัน","D":"ความบริสุทธิ์และการหลุดพ้นจากกิเลสทั้งปวง"},"correct_answer":"B","source_answer":"B. ความรู้แจ้งเห็นจริงในสัจธรรมและสติปัญญา","explanation_th":["ความรู้แจ้งเห็นจริงในสัจธรรมและสติบัญญา สัญลักษณ์นี้สื่อถึงอํานาจศักดิ์สิทธิ์และการใช้สติปัญญาตัดความหลงผิด อธิบายตัวเลือกอื่น ดังนี้ 1) ความเป็นอมตะและเป็นหนึ่งเดียวของพระเจ้า เป็นความหมายของวงกลมในสัญลักษณ์ของศาสนาซิกข์ 3) และ 4) ไม่่ใช่ความหมายหลักขององค์ประกอบในสัญลักษณ์ \"คันต้า\" (((กอก๕อ) ของศาสนาซิกข์ Ee"],"explanation_image":"assets/real-social-explanations/q079.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 79 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-080","subject":"social","question_number":80,"question_text":"พิธีกรรมในศีลมหาสนิทของศาสนาคริสต์มีการปฏิบัติที่สำคัญตรงกับข้อใด (ปป.69)","choices":{"A":"การพรมน้ำหรือการจุ่มตัวลงในน้ำ","B":"การสารภาพบาปต่อหน้ำบาทหลวง","C":"การรับประทานขนมปังและดื่มไวน์","D":"การเจิมน้ำมันศักดิ์สิทธิ์ที่หน้ำผาก"},"correct_answer":"C","source_answer":"C. การรับประทานขนมปังและดื่มไวน์","explanation_th":["การรับประทานขนมบังและดื่มไวน์ ศีลมหาสนิท เป็นพิธีกรรมที่คริสต์ศาสนิกชนจะรับประทานแผ่นบังและไวน์ ซึ่งเป็นสัญลักษณ์แทนพระกายและพระโลหิตของพระเอชูคริสต์ เพื่อระลึกถึงความรักและการเสียสละของพระองค์ในอาหาร มื้อสุดท้าย อธิบายตัวเลือกอื่น Mall 1) การพรมน้้าหรือการจุ่มตัวลงในน้้า เป็นการปฏิบัติหลักในศีลล้างบาป 2) การสารภาพบาปต่อหน้ำบาทหลวง เป็นการปฏิบัติหลักในศีลอภัยบาป 4) การเจิมน้้ามันศักดิ์สิทธิ์ที่หน้ำผาก เป็นการปฏิบัติในศีลกําลังและศีลเจิมคนไข้"],"explanation_image":"assets/real-social-explanations/q080.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 80 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-081","subject":"social","question_number":81,"question_text":"ข้อใดเป็นภัยอันตรายที่สุดต่อประชาคมโลก (ปป.69)","choices":{"A":"ภัยพิบัติทางธรรมชาติ","B":"ความขัดแย้งระหว่างรัฐชาติ","C":"การก่อการร้ายข้ามชาติ","D":"การแพร่ขยายอาวุธที่มีอานุภาพทำลายล้างสูง"},"correct_answer":"A","source_answer":"A. ภัยพิบัติทางธรรมชาติ","explanation_th":["เป็นภัยที่อันตรายที่สุดต่อประชาคมโลกในยุคบัจจุบัน เพราะเป็นภัยคุกคามที่ไร้พรมแดนและส่งผลกระทบกับคน ทั้งโลกพร้อมกัน ภัยธรรมชาติไม่่สามารถเจรจาต่อรองหรือทำสนธิสัญญาหยุดอั้งได้้เหมือนกับเรื่องอาวุธทำลายล้างสูง หรือการเมือง นอกจากนี้ยังเป็นต้นเหตุที่ทำให้เกิดวิกฤตลูกโซ่ตามมาอีกมากมาย เช่น การขาดแคลนอาหาร น้้าสะอาด การอพยพย้ายถิ่นฐาน และโรคระบาด ซึ่งสอดคล้องกับรายงานทิศทางความเสี่ยงโลกขององค์การสหประชาชาติ (UN) และ World Economic Forum ในช่วงปีหลัง ๆ"],"explanation_image":"assets/real-social-explanations/q081.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 81 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-082","subject":"social","question_number":82,"question_text":"The White Man’s Burden ส่งผลกระทบโดยตรงต่อดินแดนใดในอาเซียนมากที่สุด (ปป.68)","choices":{"A":"หมู่เกาะมลายู","B":"ดินแดนอินโดจีน","C":"หมู่เกาะอินโดนีเซีย","D":"หมู่เกาะฟิลิปปินส์"},"correct_answer":"D","source_answer":"D. หมู่เกาะฟิลิปปินส์","explanation_th":["หมู่เกาะฟิลิปปินส์ บทกวี The White Man's Burden (ภาระของคนขาว) แต่งโดย รัดยาร์ด คิปลิง (Rudyard Kipling) เพื่อสนับสนุนให้สหรัฐอเมริกาเข้ายืดครองและปกครองฟิลิปปินส์์ (หลังชนะสเปน) โดยใช้ข้ออ้างว่าเป็นภาระหน้ำที่ ของคนขาวที่เจริญแล้วที่จะต้องนำอารยธรรมไปสู่ดินแดนที่ด้อยกว่า อธิบายตัวเลือกอื่น ดังนี้ 1) หมู่เกาะมลายู ตกเป็นอาณานิคมของจักรวรรดิอังกฤษ 2) ดินแดนอินโดจีน (เวียดนาม ลาว กัมพูชา) ตกเป็นอาณานิคมของฝรั่งเศส 3) หมู่เกาะอินโดนีเซีย ตกเป็นอาณานิคมของเนเธอร์แลนด์ (ดัตข์)"],"explanation_image":"assets/real-social-explanations/q082.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 82 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-083","subject":"social","question_number":83,"question_text":"การที่กลุ่มประเทศอาเซียนร่วมมือกันจัดตั้งกองทุนและแบ่งปันวัคซีนเพื่อช่วยเหลือกันในช่วงวิกฤตการณ์แพร่ระบาดของโควิด-19 จัดเป็นการดำเนินงานภายใต้เสาหลักใดของอาเซียน (ปป.68)","choices":{"A":"ประชาคมการเมืองและความมั่นคงอาเซียน","B":"ประชาคมเศรษฐกิจอาเซียน","C":"ประชาคมสังคมและวัฒนธรรมอาเซียน","D":"ประชาคมสาธารณสุขและสิ่งแวดล้อมอาเซียน"},"correct_answer":"C","source_answer":"C. ประชาคมสังคมและวัฒนธรรมอาเซียน","explanation_th":["ประชาคมสังคมและวัฒนธรรมอาเซียน (ASCO) เป็นเสาหลักที่มุ่งเน้นการยกระดับคุณภาพชีวิตของประชาชน การสาธารณสุข การช่วยเหลือเกื้อกูลกันในยามวิกฤต และความมั่นคงของมนุษย์ ดังนั้นความร่วมมือด้านโรคระบาดจึงอยู่ใน ความรับผิดชอบของเสาหลักนี้โดยตรง อธิบายตัวเลือกอื่น ดังนี้ 1) ประชาคมการเมืองและความมั่นคงอาเซียน (APSC) เน้นเรื่องความมั่นคง สันติภาพ การทหาร และการแก้อาชญากรรม ข้ามชาติ 2) ประชาคมเศรษฐกิจอาเซียน (AEC) เน้นเรื่องการค้า การลงทุน และการรวมตัวเป็นฐานการผลิตและตลาดเดียวกัน 4) ประชาคมสาธารณสุขและสิ่งแวดล้อมอาเซียน ไม่่มีเสาหลักนี้ โชโนน้วอไผไ้นนน้โ้้ฝฝเซ"],"explanation_image":"assets/real-social-explanations/q083.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 83 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-084","subject":"social","question_number":84,"question_text":"ข้อตกลงที่ทำให้อาเซียนกลายเป็นภูมิภาคที่มีการค้าขายระหว่างกันโดยลดหรือยกเว้นภาษีศุลกากร คือกรอบความร่วมมือใด (ปป.68)","choices":{"A":"APEC","B":"AFTA","C":"WTO","D":"RCEP"},"correct_answer":"B","source_answer":"B. AFTA","explanation_th":["AFTA (ASEAN Free Trade Area) หรือ เขตการค้าเสรีอาเขียน เป็นข้อตกลงที่จัดตั้งขึ้นเพื่อส่งเสริมการค้าภายใน กลุ่มประเทศอาเซียนให้เติบโต โดยมีมาตรการสำคัญคือการลดหรือยกเว้นภาษีศุลกากรสินค้าระหว่างกัน อธิบายตัวเลือกอื่น ดังนี้ 1) APEC (Asia-Pacific Economic Cooperation) คือ ความรวมมือทางเศรษฐกิจเอเชีย-แปซิฟิก (ครอบคลุมหลายประเทศ รอบมหาสมุทรแปซิฟิก) 3) WTO (World Trade Organization) คือ องค์การการค้าโลก (องค์กรระดับสากล) 4) RCEP (Regional Comprehensive Economic Partnership) คือ ความตกลงหุ้นส่วนทางเศรษฐกิจระดับภูมิภาค (อาเซียน + 5 ประเทศคู่เจรจา ซึ่งมีสเกลใหญ่กว่า AFTA)"],"explanation_image":"assets/real-social-explanations/q084.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 84 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-085","subject":"social","question_number":85,"question_text":"ถ้าต้องการศึกษาเกี่ยวกับศาสนาคริสต์ ต้องไปประเทศใดในอาเซียน (ปป.68)","choices":{"A":"อินโดนีเซีย","B":"เมียนมา","C":"ฟิลิปปินส์","D":"มาเลเซีย"},"correct_answer":"C","source_answer":"C. ฟิลิปปินส์","explanation_th":["ฟิลิปปินส์ เป็นประเทศเดียวในกลุ่มอาเซียนที่มีประชากรส่วนใหญ่ นับถือศาสนาคริสต์ โดยเฉพาะนิกาย 'โรมันคาทอลิก สาเหตุหลักมาจากการที่ฟิลิปปินส์เคยตกเป็นอาณานิคมของประเทศสเปนมาอย่างยาวนานกว่า 300 ปี อธิบายตัวเลือกอื่น ดังนี้ 1) อินโดนีเซีย ประชากรส่วนใหญ่นับถือศาสนาอิสลาม (และเป็นประเทศที่มีประชากรมุสลิมมากที่สุดในโลก) 2) เมียนมา ประชากรส่วนใหญ่นับถือศาสนาพุทธ (นิกายเถรวาท) 4) มาเลเซีย ประชากรส่วนใหญ่นับถือศาสนาอิสลาม (เป็นศาสนาประจำชาติ)"],"explanation_image":"assets/real-social-explanations/q085.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 85 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-086","subject":"social","question_number":86,"question_text":"อาเซียนต้องการให้ประชาคมอาเซียนเป็นตลาดและฐานการผลิตเดียวกัน ถือเป็นความร่วมมือระดับใด (ปป.69)","choices":{"A":"เขตการค้าเสรี","B":"สหภาพศุลกากร","C":"ตลาดร่วม","D":"สหภาพเศรษฐกิจ"},"correct_answer":"C","source_answer":"C. ตลาดร่วม","explanation_th":["ตลาดรวม การเป็นตลาดและฐานการผลิตเดียวกันของประชาคมเศรษฐกิจอาเซียน (AEC) เป็นลักษณะของ ความร่วมมือระดับตลาดร่วม คือมีการเคลื่อนย้ายสินค้า บริการ การลงทุน และแรงงานฝีมือระหว่างกันได้้อย่างเสรี อธิบายตัวเลือกอื่น Mil 1) เขตการค้าเสรี (Free Trade Area) เป็นขั้นพื้นฐานกว่าตลาดร่วม คือลดภาษีศุลกากรระหว่างกัน แต่ยังไม่่เปิดเสรีแรงงาน หรือการลงทุนเต็มรูปแบบ (อาเซียนเคยอยู่ขั้นนี้คือ AFTA) 2) สหภาพศุลกากร (Customs Union) คือเขตการค้าเสร็ที่มีการกําหนดอัตราภาษีนำเข้าจากประเทศนอกกลุ่มในอัตรา เดียวกัน (อาเซียนยังไปไม่่ถึงขั้นนี้แบบสมบูรณ์) 4) สหภาพเศรษฐกิจ (Economic Union) เป็นขั้นสูงสุดที่มีการใช้นโยบายเศรษฐกิจและการเงินร่วมกัน (เช่น การใช้สกุลเงิน เดียวกันแบบสหภาพยุโรปหรือ 6ป) ชรชรโญไ ป"],"explanation_image":"assets/real-social-explanations/q086.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 86 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-087","subject":"social","question_number":87,"question_text":"ประเทศใดไม่่ได้้เป็นรัฐสมาชิกตามความตกลงว่าด้วยความร่วมมือเพื่อการพัฒนาลุ่มแม่น้ำโขงอย่างยั่งยืน (ปป.69)","choices":{"A":"ไทย","B":"กัมพูชา","C":"เวียดนาม","D":"เมียนมาร์์"},"correct_answer":"D","source_answer":"D. เมียนมาร์์","explanation_th":["เมียนมาร์์ ความตกลงนี้เป็นจุดกําเนิดของคณะกรรมาธิการแม่น้้าโขงซึ่งมีสมาชิกเต็มรูปแบบเพียง 4 ประเทศที่อยู่ ตอนล่างของแม่นั้าโขง ได้้แก่ ไทย ลาว กัมพูชา และเวียดนาม ส่วน เมียนมาร์์และจีน มีสถานะเป็นเพียงประเทศคู่เจรจา เท่านั้น อธิบายตัวเลือกอื่น Mail 1) ไทย เป็นรัฐสมาชิกตั้งเดิมและเป็นแกนนำหลัก 2) กัมพูชา เป็นรัฐสมาชิกดั้งเดิม 3) เวียดนาม เป็นรัฐสมาชิกตั้งเติม"],"explanation_image":"assets/real-social-explanations/q087.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 87 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-088","subject":"social","question_number":88,"question_text":"หนังตะลุง ‘วายัง กูลิต’ (Wayang Kulit) มีต้นกำเนิดจากเกาะและประเทศใด (ปป.69)","choices":{"A":"เกาะลูซอน ประเทศฟิลิปปินส์","B":"เกาะปีนัง ประเทศมาเลเซีย","C":"เกาะชวา ประเทศอินโดนีเซีย","D":"เกาะติมอร์ ประเทศติมอร์-เลสเต"},"correct_answer":"B","source_answer":"B. เกาะปีนัง ประเทศมาเลเซีย","explanation_th":["88. เฉลย ข้อ 3. เกาะชวา ประเทศอินโดนีเซีย วายัง กูลิต เป็นศิลปะการแสดงเชิดหุ่นเงาโบราณที่ทำจากหนังควายหรือหนังแกะ ซึ่งมีต้นกําเนิดและโด่งดังมากในเกาะชวาและเกาะบาหลี ประเทศอินโดนีเซีย โดยมักจะแสดงเรื่องราวจากมหากาพย์รามายณะ และมหาภารตะ อธิบายตัวเลือกอื่น ดังนี้ 1) เกาะลูชอน ประเทศฟิลิปปินส์์ ไม่่ใช่ต้นกําเนิดของวายัง กูลิต 2) เกาะปีนัง ประเทศมาเลเซีย มีการรับเอาวัฒนธรรมหนังตะลุงไปเล่นบ้าง (เรียกว่า วายัง ew) แต่ต้นตํารับจริง ๆ อยู่ที่อินโดนีเซีย 4) เกาะติมอร์ ประเทศติมอร์-เลสเต ไม่่ใช่ต้นกําเนิดของศิลปะแขนงนี้"],"explanation_image":"assets/real-social-explanations/q088.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2569,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 88 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-089","subject":"social","question_number":89,"question_text":"ตำแหน่งใดในอาเซียนหมุนเวียนทุก 1 ปี โดยเรียงตามตัวอักษร (ปป.68)","choices":{"A":"คณะมนตรีอาเซียน","B":"ประธานอาเซียน","C":"เลขาธิการอาเซียน","D":"คณะกรรมาธิการสิทธิมนุษยชน"},"correct_answer":"B","source_answer":"B. ประธานอาเซียน","explanation_th":["ประธานอาเซียน เป็นตําแหน่งที่จะเวียนกันเป็นเจ้าภาพในกลุ่มประเทศสมาชิกทุก ๆ 1 ปี โดยเรียงลําดับตาม ตัวอักษรภาษาอังกฤษของชื่อประเทศ (เช่น บรูไน -> กัมพูชา -> อินโดนีเซีย -> ลาว -> มาเลเซีย) อธิบายตัวเลือกอื่น ดังนี้ 1) คณะมนตรีอาเซียน ไม่่ใช่ตําแหน่งบุคคลที่หมุนเวียนรายปี แต่เป็นกลไกการประชุมระดับรัฐมนตรี 3) เลขาธิการอาเซียน มีวาระการดํารงตําแหน่ง 5 ปี (ไม่่สามารถต่ออายุได้้) หมุนเวียนตามตัวอักษรภาษาอังกฤษของชื่อ ประเทศเช่นกัน 4) คณะกรรมาธิการสิทธิมนุษยชน เป็นหน่วยงาน ไม่่ใช่ตําแหน่งที่หมุนเวียน 1 ปีตามตัวอักษร ณงผณค้ณณซ ฐ ขข เฟ"],"explanation_image":"assets/real-social-explanations/q089.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 89 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-090","subject":"social","question_number":90,"question_text":"การดำเนินการระหว่างอาเซียนกับประเทศญี่ปุ่น จัดอยู่ในกรอบความร่วมมือแบบใด (ปป.68)","choices":{"A":"อาเซียน +1","B":"อาเซียน +3","C":"อาเซียน +6","D":"อาเซียน +8"},"correct_answer":"A","source_answer":"A. อาเซียน +1","explanation_th":["อาเซียน +1 กรอบความร่วมมือระหว่างอาเซียน (ทั้ง 10 ประเทศ) กับประเทศคู่เจรจาเพียง 1 ประเทศ จะเรียกว่า อาเซียน +1 (ASEAN+1) ในกรณีนี้คือ อาเซียน-ญี่ปุ่น (ส่วนอาเซียน+1 อื่น ๆ เช่น อาเซียน-จีน, อาเซียน-อินเดีย) อธิบายตัวเลือกอื่น ดังนี้ 2) อาเซียน +3 คือความร่วมมือระหว่างอาเซียน 10 ประเทศ + จีน ญี่ปุ่น และเกาหลีใต้ 3) อาเซียน +6 คือความร่วมมือระหว่างอาเซียน 10 ประเทศ + จีน ญี่ปุ่น เกาหลีใต้ ออสเตรเลีย นิวซีแลนด์ และอินเดีย 4) อาเซียน +8 หมายถึง กรอบการประชุมรัฐมนตรีกลาโหมอาเซียนบวกแปด (ADMM-Plus) ซึ่งมีคู่เจรจา 8 ประเทศ"],"explanation_image":"assets/real-social-explanations/q090.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2568,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 90 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-091","subject":"social","question_number":91,"question_text":"ข้อใดคือกฎหมายสูงสุดของอาเซียน (ปป.64)","choices":{"A":"กฎบัตรอาเซียน","B":"ปฏิญญากรุงเทพ","C":"กฎหมายระหว่างประเทศ","D":"กฎหมายมนุษยธรรมระหว่างประเทศ"},"correct_answer":"A","source_answer":"A. กฎบัตรอาเซียน","explanation_th":["กฎบัตรอาเซียน (ASEAN Charter) เปรียบเสมือนรัฐธรรมนูญหรือกฎหมายสูงสุดของอาเซียน ที่วางกรอบทาง กฎหมาย โครงสร้างองค์กร และเบ้าหมายของประชาคมอาเซียนให้ประเทศสมาชิกต้องปฏิบัติตาม เพื่อให้อาเซียนมีสถานะ เป็นนิติบุคคล อธิบายตัวเลือกอื่น ดังนี้ 2) ปฏิญญากรุงเทพ (Bangkok Declaration) คือเอกสารก่อตั้งอาเซียนเมื่อปี พ.ศ. 2510 (ไม่่ใช่กฎหมายสูงสุด) 3) กฎหมายระหว่างประเทศ เป็นกฎหมายกว้าง ๆ ที่ใช้บังคับความสัมพันธ์ระหว่างรัฐทั่วโลก ไม่่ใช่ของอาเซียนโดยเฉพาะ 4) กฎหมายมนุษยธรรมระหว่างประเทศ เป็นกฎหมายที่ใช้ในยามสงครามเพื่อคุ้มครองผู้ที่ไม่่เกี่ยวข้องกับการสู้รบ"],"explanation_image":"assets/real-social-explanations/q091.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2564,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 91 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-092","subject":"social","question_number":92,"question_text":"สีเหลืองในสัญลักษณ์อาเซียนหมายถึงข้อใด (อก.58)","choices":{"A":"ความบริสุทธิ์","B":"ความเจริญรุ่งเรือง","C":"สันติภาพและความมั่นคง","D":"ความก้าวหน้ำ"},"correct_answer":"B","source_answer":"B. ความเจริญรุ่งเรือง","explanation_th":["ความเจริญรุ่งเรือง รวงข้าวสีเหลือง 10 ต้นมัดรวมกันในสัญลักษณ์อาเซียน สื่อถึงประเทศสมาชิกทั้ง 10 ประเทศ ที่รวมกันเพื่อมิตรภาพและความเป็นน้้าหนึ่งใจเดียวกัน และสีเหลืองหมายถึงความเจริญรุ่งเรือง อธิบายตัวเลือกอื่น ดังนี้ 1) ความบริสุทธิ์ ตรงกับสีขาว 3) สันติภาพและความมั่นคง ตรงกับสีน้้าเงิน 4) ความก้าวหน้ำ (ความกล้าหาญและพลังความก้าวหน้ำ) ตรงกับสีแดง"],"explanation_image":"assets/real-social-explanations/q092.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2558,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 92 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-093","subject":"social","question_number":93,"question_text":"ตัวย่อของเขตการค้าเสรีของอาเซียนคือข้อใด (ปป.66)","choices":{"A":"APEC","B":"AFTA","C":"EFTA","D":"NAFTA"},"correct_answer":"B","source_answer":"B. AFTA","explanation_th":["AFTA (ASEAN Free Trade Area) คือ เขตการค้าเสรีอาเซียน ซึ่งเป็นข้อตกลงเพื่อลดภาษีศุลกากรระหว่างประเทศ สมาชิกอาเซียนให้เหลือน้อยที่สุด เพื่อดึงดูดการลงทุนและเพิ่มศักยภาพการแข่งขัน อธิบายตัวเลือกอื่น ดังนี้ 1) APEC คือ ความรวมมือทางเศรษฐกิจเอเชีย-แปซิพิก 9) EFTA คือ สมาคมการค้าเสรีแห่งยุโรป 4) NAFTA Ao ข้อตกลงการค้าเสรือเมริกาเหนือ (บัจจุบันเปลี่ยนชื่อเป็น USMCA uaa) โชโนน้วอไผไ้นนน้โ้้ฝฝเซ"],"explanation_image":"assets/real-social-explanations/q093.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 93 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-094","subject":"social","question_number":94,"question_text":"ประเทศไทยได้้รับมอบหมายเป็นผู้ประสานงานหลักสาขาใดในการนำร่องตามแผนการดำเนินงานของอาเซียน (ปป.60)","choices":{"A":"สาขาโลจิสติกส์","B":"สาขายานยนต์","C":"สาขาการท่องเที่ยว","D":"สาขาอิเล็กทรอนิกส์"},"correct_answer":"C","source_answer":"C. สาขาการท่องเที่ยว","explanation_th":["สาขาการท่องเที่ยว ในการรวมตัวเป็นประชาคมเศรษฐกิจอาเซียน (AEC) ได้้มีการแบ่งหน้ำที่ให้ประเทศสมาชิกเป็นผู้ ปประสานงานหลัก (Lead Country) ในสินค้าและบริการนำร่องต่าง ๆ โดยประเทศไทยรับผิดชอบ 2 สาขาหลัก คือ การท่องเที่ยวและการบิน อธิบายตัวเลือกอื่น ดังนี้ 1) สาขาโลจิสติกส์ ไม่่มีประเทศนำร่องแบบเดี่ยว ๆ แต่เป็นความร่วมมือภาพรวม 2) สาขายานยนต์ เป็นหน้ำที่ผู้ประสานงานหลักของประเทศอินโดนีเซีย 4) สาขาอิเล็กทรอนิกส์ เป็นหน้ำที่ผู้ประสานงานหลักของประเทศฟิลิปปินส์์"],"explanation_image":"assets/real-social-explanations/q094.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2560,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 94 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-095","subject":"social","question_number":95,"question_text":"การประชุม APEC 2022 ที่ประเทศไทยเป็นเจ้าภาพ สอดคล้องกับเสาหลักใดในอาเซียนมากที่สุด (อก.65)","choices":{"A":"การเมือง","B":"เศรษฐกิจ","C":"สังคม","D":"ทหารและกองทัพ"},"correct_answer":"B","source_answer":"B. เศรษฐกิจ","explanation_th":["เศรษฐกิจ APEC (Asia-Pacific Economic Cooperation) คือกรอบความรวมมือทางเศรษฐกิจ เอเชีย-แปซิฟิก มีเบ้าหมายเพื่อส่งเสริมการค้าเสรีและการลงทุน ดังนั้นจึงสอดคล้องกับ เสาหลักประชาคมเศรษฐกิจอาเซียน (AEC) มากที่สุด อธิบายตัวเลือกอื่น ดังนี้ 1) การเมือง สอดคล้องกับเสาหลักประชาคมการเมืองและความมั่นคงอาเซียน (APSC) 3) สังคม สอดคล้องกับเสาหลักประชาคมสังคมและวัฒนธรรมอาเซียน (ASCO) 4) ทหารและกองทัพ เป็นส่วนหนึ่งของความร่วมมือด้านความมั่นคง ไม่่ใช่เบ้าหมายของ APEC"],"explanation_image":"assets/real-social-explanations/q095.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2565,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 95 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-096","subject":"social","question_number":96,"question_text":"มหาสถูปเจดีย์บุโรพุทโธ (Borobudur) ตั้งอยู่ในประเทศใด (ตม.66)","choices":{"A":"สิงคโปร์","B":"มาเลเซีย","C":"ฟิลิปปินส์","D":"อินโดนีเซีย"},"correct_answer":"D","source_answer":"D. อินโดนีเซีย","explanation_th":["อินโดนีเซีย มหาสถูปบุโรพุทโธ (8๐6๐๒นอ0 เป็นศาสนสถานของศาสนาพุทธนิกายมหายานที่ใหญ่ที่สุดในโลก ตั้งอยู่บนเกาะชวา ประเทศอินโดนีเซีย สร้างขึ้นตั้งแต่สมัยที่ดินแดนแถบนี้ยังรุ่งเรืองด้วยศาสนาพุทธและพราหมณ์-ฮินดู ก่อนที่จะเปลี่ยนมารับศาสนาอิสลามในภายหลัง อธิบายตัวเลือกอื่น Mail 1) สิงคโปร์ เป็นเกาะเล็ก ๆ ที่เจริญด้านเศรษฐกิจและนวัตกรรม ไม่่มีโบราณสถานขนาดใหญ่ระดับนี้ 2) มาเลเซีย มีสถานที่สำคัญทางประวัติศาสตร์เช่นกัน (เช่น เมืองมะละกา) แต่ไม่่ไขที่ตั้งของบุโรพุทโธ 3) ฟิลิปปินส์ โบราณสถานส่วนใหญ่จะเป็นโบสถ์คริสต์ที่สร้างในยุคอาณานิคมสเปน"],"explanation_image":"assets/real-social-explanations/q096.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 96 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-097","subject":"social","question_number":97,"question_text":"ประเทศกัมพูชามีพรมแดนติดต่อกับกี่ประเทศ อะไรบ้าง (ตม.66)","choices":{"A":"2 ประเทศ คือ ไทย ลาว","B":"2 ประเทศ คือ ไทย เวียดนาม","C":"3 ประเทศ คือ ไทย ลาว เมียนมา","D":"3 ประเทศ คือ ไทย ลาว เวียดนาม"},"correct_answer":"D","source_answer":"D. 3 ประเทศ คือ ไทย ลาว เวียดนาม","explanation_th":["3 ประเทศ คือ ไทย ลาว เวียดนาม หากเรานึกภาพแผนที่เอเชียตะวันออกเฉียงใต้ กัมพูชาจะถูกขนาบข้างด้วย 3 ประเทศ Ao ทิศตะวันตกและทิศเหนือติดกับไทย ทิศตะวันออกเฉียงเหนือติดกับลาว และทิศตะวันออกและทิศใต้ติดกับ เวียดนาม อธิบายตัวเลือกอื่น ดังนี้ 1) และ 2) จำนวนประเทศไม่ครบ กัมพูชาติดกับ 3 ประเทศ ไม่ใช 2 ประเทศ 3) 3 ประเทศ คือ ไทย ลาว หม่า ผิดตรงเมียนมาร์์เพราะเมียนมาร์์อยู่ทางฝั่งตะวันตกของไทย ไม่่ได้้มีพรมแดนส่วนใดกับ กัมพูชาเลย ชรชรโญไ ป"],"explanation_image":"assets/real-social-explanations/q097.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 97 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-098","subject":"social","question_number":98,"question_text":"ข้อใดคือสกุลเงินของประเทศกัมพูชา มาเลเซีย ฟิลิปปินส์ และเมียนมาร์์ ตามลำดับ (ปป.64)","choices":{"A":"เรียล ดอง เปโซ จ๊าด","B":"เรียล ริงกิต เปโซ จ๊าด","C":"เปโซ ริงกิต รูเปียห์ กีบ","D":"จ๊าด เปโซ ริงกิต รูเปียห์"},"correct_answer":"B","source_answer":"B. เรียล ริงกิต เปโซ จ๊าด","explanation_th":["Gua ริงกิต เปโซ sia เป็นการจับคู่สกุลเงินประจำชาติที่ถูกต้องตามลําดับ คือ กัมพูชา (เรียล - Riel), มาเลเซีย Ga fin - Ringgit), ฟิลิปปินส์ (เปโซ - Peso), และเมียนมาร์์ (Gia - Kyat) อธิบายตัวเลือกอื่น ดังนี้ 1) ผิดที่ ดอง เพราะดองเป็นสกุลเงินของประเทศเวียดนามไม่่ใช่มาเลเซีย 3) สลับตําแหน่งกัน และมีรูเบียร์ (ใน๓8) ซึ่งเป็นสกุลเงินของอินโดนีเซีย รวมถึงกีบ (kip) ซึ่งเป็นสกุลเงินของลาว 4) สลับตําแหน่งกัน และมีรูเบียร์ซึ่งเป็นสกุลเงินของอินโดนีเซีย"],"explanation_image":"assets/real-social-explanations/q098.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2564,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 98 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-099","subject":"social","question_number":99,"question_text":"ทุ่งไหหินตั้งอยู่ในประเทศใด (ตม.66)","choices":{"A":"ลาว","B":"สิงคโปร์","C":"เวียดนาม","D":"มาเลเซีย"},"correct_answer":"A","source_answer":"A. ลาว","explanation_th":["an ทุ่งไหหิน เป็นแหล่งโบราณคดีที่สำคัญมาก ตั้งอยู่ในแขวงเชียงขวาง ประเทศลาว มีลักษณะเป็นหินทรายสลัก รูปทรงคล้ายไหขนาดใหญ่วางกระจายอยู่เต็มทุ่งกว้าง สันนิษฐานว่าสร้างขึ้นในยุคเหล็กเพื่อใช้ในพิธีกรรมเกี่ยวกับงานศพ อธิบายตัวเลือกอื่น ดังนี้ 2) สิงคโปร์ ภูมิประเทศเป็นเกาะเมืองท่า ไม่่มีแหล่งโบราณคดีลักษณะนี้ 3) เวียดนาม มีสถานที่สำคัญทางธรรมชาติและประวัติศาสตร์เช่นกัน (เช่น ฮาลองเบย์) แตไม่่ใช่ทุ่งไหหิน 4) มาเลเซีย มีสถานที่ท่องเที่ยวทางธรรมชาติที่โด่งดัง (เช่น ถ้าบาตู ยอดเขาคินาบาลู) แต่ไม่่ใช่ทุ่งไหหิน"],"explanation_image":"assets/real-social-explanations/q099.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 99 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true},{"id":"actual-guru-social-100","subject":"social","question_number":100,"question_text":"ประเทศไทยไม่่ได้้มีพรมแดนติดต่อกับประเทศใด (ตม.66)","choices":{"A":"กัมพูชา","B":"เวียดนาม","C":"มาเลเซีย","D":"เมียนมาร์์"},"correct_answer":"B","source_answer":"B. เวียดนาม","explanation_th":["เวียดนาม ประเทศไทยมีพรมแดนทางบกติดต่อกับเพื่อนบ้านเพียง 4 ประเทศเท่านั้น คือ เมียนมาร์์ (ทิศตะวันตก และเหนือ), ลาว (ทิศเหนือและอีสาน), กัมพูชา (ทิศตะวันออก), และมาเลเซีย (ela) ส่วนเวียดนาม จะถูกคั่นกลางด้วย ประเทศลาวและกัมพูชา ทำให้ไม่่มีพรมแดนส่วนใดติดกับไทยเลย อธิบายตัวเลือกอื่น ดังนี้ 1) กัมพูชา มีพรมแดนติดต่อกับไทยทางภาคตะวันออก 3) มาเลเซีย มีพรมแดนติดต่อกับไทยทางภาคใต้ 4) เมียนมาร์์ มีพรมแดนติดต่อกับไทยทางภาคเหนือและตะวันตกยาวที่สุด — ย ็ั้ญ้ญญ ้้นนฬาไั้ไไไฬ็๊้็โซในี์์:"],"explanation_image":"assets/real-social-explanations/q100.jpg","explanation_author":"source","answer_verified":true,"choices_verified":true,"year":2566,"exam_track":"รวมทุกสาย","provider":"guru-police","source_id":"local-guru-actual-social","source_locator":"ข้อ 100 · OCR Extract PDF","explanation_source_id":"local-guru-actual-social-answer","evidence_level":"A","representation":"actual","eligible":true}];const ids=new Set(d.questions.map(q=>q.id));d.questions.push(...rows.filter(q=>!ids.has(q.id)));})();
